&lt;h1 id=&#34;web210&#34;&gt;&lt;a href=&#34;#web210&#34; class=&#34;headerlink&#34; title=&#34;web210&#34;&gt;&lt;/a&gt;web210&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;--tamper 的4体验


查询语句
//拼接sql语句查找指定ID用户
$sql = &amp;quot;select id,username,pass from ctfshow_user where id = (&amp;#39;&amp;quot;.$id.&amp;quot;&amp;#39;) limit 0,1;&amp;quot;;


返回逻辑
//对查询字符进行解密
  function decode($id)&amp;#123;
    return strrev(base64_decode(strrev(base64_decode($id))));
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
