if(isset($_GET[&amp;#39;v1&amp;#39;]))&amp;#123;
    $v1 = (String)$_GET[&amp;#39;v1&amp;#39;];
    if(is_numeric($v1))&amp;#123;
        $d = (int)($v1 * 0x36d * 0x36d * 0x36d * 0x36d * 0x36d);
        sleep($d);
        echo file_get_contents(&amp;quot;flag.php&amp;quot;);
    &amp;#125;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;0x36d&lt;/code&gt;这是 16进制表示法，十进制是：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;0x36d = 3*16^2 + 6*16 + 13 = 3*256 + 96 + 13 = 768 + 96 + 13 = 877
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;所以 &lt;code&gt;0x36d&lt;/code&gt; 就是 &lt;code&gt;877&lt;/code&gt;。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;表达式里 &lt;code&gt;$v1 * 0x36d * 0x36d * 0x36d * 0x36d * 0x36d&lt;/code&gt; 就是 &lt;code&gt;$v1 * 877^5&lt;/code&gt; （877 的五次方再乘以 &lt;code&gt;$v1&lt;/code&gt;）。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?v1=0
?v1=0x0		16进制
?v1=0e123	科学计数法
&lt;/code&gt;&lt;/pre&gt;
